export default {
	// Called when vendorDropdown changes on Create PO drawer
	populateForVendor: async (selected_vendor_id) => {
		let vID = null;
		try { vID = selected_vendor_id; } catch (e) { return; }

		storeValue('poLines', []);
		storeValue('poMode', 'CREATE');

		if (!Products.data || !vID) { return; }

		const newLines = (Products.data.data || Products.data)
		.filter(p => Number(p.vendor_id) === Number(vID))
		.map((p, index) => ({
			"S.No": index + 1,
			"EAN Code": p.ean_code,
			"Item Name": p.product_name,
			"MRP": Number(p.mrp),
			"Price": Number(p.purchase_rate),
			"Qty": 0,
			"Sch": 0,
			"Disc %": 0,
			"GST %": Number(p.tax_percentage),
			"Gross $": 0,
			"Disc. $": 0,
			"Taxable $": 0,
			"Stock": Number(p.current_stock),
			"GST $": 0,
			"Net $": 0,
			"_product_id": p.id
		}));

		storeValue('poLines', newLines);
	}
}

export default {
  onCellChange: () => {
    const changes = poTable.updatedRow ? [poTable.updatedRow] : [];
    if (changes.length === 0) return;

    const change = changes[0];
    const targetProductId = change._product_id;
    const currentLines = appsmith.store.poLines || [];

    const targetIndex = currentLines.findIndex(row =>
      row._product_id === targetProductId || row.product_id === targetProductId
    );
    if (targetIndex === -1) return;

    const updated = currentLines.map((row, i) => {
      if (i !== targetIndex) return row;
      const merged = { ...row, ...change };
      const Qty     = Number(merged.Qty) || 0;
      const Price   = Number(merged.Price) || 0;
      const Sch     = Number(merged.Sch) || 0;
      const DiscPct = Number(merged["Disc %"]) || 0;
      const GstPct  = Number(merged["GST %"]) || 5;
      const Gross   = Qty * Price;
      const DiscAmt = (Gross - Sch) * (DiscPct / 100);
      const Taxable = Gross - Sch - DiscAmt;
      const Tax     = Taxable * (GstPct / 100);
      return { ...merged,
        "Gross $": Gross, "Disc. $": DiscAmt,
        "Taxable $": Taxable, "GST $": Tax, "Net $": Taxable + Tax
      };
    });
    storeValue('poLines', updated);
  }
}

export default {
  viewPO: async () => {
    await getPOById.run();
    const data = getPOById.data;
    if (!data || !data.header) {
      showAlert('No Data Found', 'error'); return;
    }
    storeValue('poMode', 'VIEW');
    storeValue('selectedVendorId', data.header.vendor_id);
    storeValue('selectedPONumber', data.header.po_number);
    storeValue('selectedPODate', data.header.po_date);
    storeValue('selectedDeliveryDate', data.header.delivery_date);
		storeValue('selectedPOId',data.header.id);
		storeValue('selectedPO',data.header.status)


    const formattedLines = (data.lines || []).map((row, index) => {
      const qty     = Number(row.ordered_qty);
      const rate    = Number(row.rate);
      const discPct = Number(row.discount_percent || 0);
      const scheme  = Number(row.scheme_amount || 0);
      const gross   = qty * rate;
      const discAmt = (gross - scheme) * (discPct / 100);
      const taxAmt  = Number(row.tax_amount);
      const net     = Number(row.amount);
      return {
        "S.No": index + 1, "EAN Code": row.ean_code,
        "Item Name": row.product_name, "MRP": Number(row.mrp),
        "Price": rate, "Qty": qty, "Sch": scheme,
        "Disc %": discPct, "GST %": 5,
        "Gross $": gross, "Disc. $": discAmt,
        "Taxable $": net - taxAmt, "GST $": taxAmt, "Net $": net,
        "_product_id": row.product_id
      };
    });
    storeValue('poLines', formattedLines);
    showModal(drawerCreatePO.name);
  }
}

export default {
  editPO: async () => {
    storeValue('poLines', []);
    storeValue('poMode', 'EDIT');
    const masterProducts = Products.data.data || [];
    const savedLines = getPOById.data.lines || [];
    const vendorId = appsmith.store.selectedVendorId;

    const mergedLines = masterProducts
      .filter(p => Number(p.vendor_id) === Number(vendorId))
      .map((p, index) => {
        const saved   = savedLines.find(s => Number(s.product_id) === Number(p.id));
        const qty     = saved ? Number(saved.ordered_qty) : 0;
        const rate    = saved ? Number(saved.rate) : Number(p.purchase_rate);
        const disc    = saved ? Number(saved.discount_percent) : 0;
        const scheme  = saved ? Number(saved.scheme_amount) : 0;
        const gross   = qty * rate;
        const discAmt = (gross - scheme) * (disc / 100);
        const gstPct  = 5;
        const taxAmt  = (gross - scheme - discAmt) * (gstPct / 100);
        const net     = (gross - scheme - discAmt) + taxAmt;
        return {
          "S.No": index+1, "EAN Code": p.ean_code, "Item Name": p.product_name,
          "MRP": Number(p.mrp), "Price": rate, "Qty": qty, "Sch": scheme,
          "Disc %": disc, "GST %": gstPct, "Gross $": gross,
          "Disc. $": discAmt, "Taxable $": net - taxAmt,
          "GST $": taxAmt, "Net $": net, "_product_id": p.id
        };
      });
    storeValue('poLines', mergedLines);
    showModal(drawerCreatePO.name);
  }
}

export default {
  onVendorSelect: () => {
    const vID = vendorDropdownGRN.selectedOptionValue;
    storeValue('piLines', []);
    if (!Products.data || !vID) { return; }

    const productList = Products.data.data || Products.data;
    const newLines = productList
      .filter(p => Number(p.vendor_id) === Number(vID))
      .map((p, index) => ({
        "S.No": index + 1,
        "EAN Code": p.ean_code || "",
        "Item Name": p.product_name,
        "MRP": Number(p.mrp),
        "Price": Number(p.purchase_rate),
        "Qty": 0, "Sch": 0, "Disc %": 0,
        "GST %": Number(p.tax_percentage || 5),
        "Gross $": 0, "Disc. $": 0, "Taxable $": 0, "GST $": 0, "Net $": 0,
        "Batch No": "", "Expiry": null,
        "_product_id": p.id
      }));
    storeValue('piLines', newLines);
  },

  addMissingProducts: () => {
    const currentRows = appsmith.store.piLines || [];
    const allProducts = Products.data.data || Products.data;
    const vID = vendorDropdownGRN.selectedOptionValue;
    if (!allProducts || !vID) return;

    const missingProds = allProducts.filter(p =>
      Number(p.vendor_id) === Number(vID) &&
      !currentRows.find(row => Number(row._product_id) === Number(p.id))
    );
    const newRows = missingProds.map((p, i) => ({
      "S.No": currentRows.length + i + 1,
      "EAN Code": p.ean_code || "",
      "Item Name": p.product_name,
      "MRP": Number(p.mrp), "Price": Number(p.purchase_rate),
      "Qty": 0, "Sch": 0, "Disc %": 0,
      "GST %": Number(p.tax_percent || 5),
      "Gross $": 0, "Disc. $": 0, "Taxable $": 0, "GST $": 0, "Net $": 0,
      "Batch No": "", "Expiry": null, "_product_id": p.id
    }));
    storeValue('piLines', [...currentRows, ...newRows]);
    showAlert(`Added ${newRows.length} products`, 'success');
  }
}

export default {
	saveGRN: async () => {
		// 1. Validation
		const rawLines = appsmith.store.piLines || [];
		const validLines = rawLines.filter(row => row.Qty && Number(row.Qty) > 0);

		if (validLines.length === 0) {
			showAlert('No items to save!', 'error'); 
			return;
		}

		const vID = vendorDropdownGRN.selectedOptionValue;
		if (!vID) { 
			showAlert('Select a Vendor', 'error'); 
			return; 
		}

		// 2. Prepare Detailed Line Items
		const dbLines = validLines.map(row => {
			const qty = Number(row.Qty);
			const price = Number(row.Price);
			const scheme = Number(row.Sch || 0);
			const discPercent = Number(row['Disc %'] || 0);
			const tax = Number(row['GST $'] || 0);

			// Calculation Formula
			const gross = qty * price;
			const discountAmount = (gross - scheme) * (discPercent / 100);
			const taxableAmount = gross - scheme - discountAmount;
			const netAmount = taxableAmount + tax;

			return {
				product_id:       Number(row._product_id),
				ordered_qty:      0, 
				accepted_qty:     qty,
				rate:             price,
				discount_percent: discPercent,
				discount_amount:  discountAmount, // Now saved in DB
				scheme_amount:    scheme,
				tax_amount:       tax,
				amount:           netAmount,      // Corrected to Net Amount
				batch_number:     row["Batch No"] ? row["Batch No"].toString() : "DEFAULT",
				expiry_date:      row.Expiry ? new Date(row.Expiry).toISOString().split('T')[0] : null,
				mrp:              Number(row.MRP || 0)
			};
		});

		// 3. Calculate Header Totals
		const totalTaxable = dbLines.reduce((acc, x) => acc + (x.amount - x.tax_amount), 0);
		const totalTax = dbLines.reduce((acc, x) => acc + x.tax_amount, 0);
		const grandTotal = totalTaxable + totalTax;

		const finalPayload = {
			vendor_id:         Number(vID),
			purchase_order_id: Number(ChoosePo.selectedOptionValue || 0),
			invoice_number:    vendorInvoiceNo.text,
			invoice_date:      dateVendorInvoice.selectedDate,
			received_date:     dateReceived.selectedDate,

			// Header Totals
			total_net:         totalTaxable, // Sum of taxable amounts
			tax_amount:        totalTax,
			grand_total:       grandTotal,

			parent_invoice_id: appsmith.store.CorrectionID || null,
			lines:             dbLines
		};

		// 4. Send & Cleanup
		await storeValue('grnPayload', finalPayload);
		await saveGRN.run(); // Ensure this matches your API query name

		showAlert("GRN Saved Successfully", "success");
		closeModal(modalFrameGRN.name);
		await getGRNList.run();
		await getPOs.run();
	}
}

export default {
  makePayment: async () => {
    const vendor = appsmith.store.selectedVendor;
    const totalAmount = Number(payAmount.text);
    const isRefund = payType.selectedOptionValue === 'REFUND';

    if (!totalAmount || totalAmount <= 0) {
      showAlert('Enter valid amount', 'error'); return;
    }

    let allocations = [];
    if (!isRefund) {
      const selectedBills = tblPendingBills.selectedRows || [];
      let remaining = totalAmount;
      for (const bill of selectedBills) {
        if (remaining <= 0) break;
        const alloc = Math.min(Number(bill['Balance $']), remaining);
        if (alloc > 0) {
          allocations.push({ invoice_id: bill.id, amount: alloc });
          remaining -= alloc;
        }
      }
    }

    const payload = {
      vendor_id:       vendor.id,
      amount:          totalAmount,
      payment_date:    payDate.selectedDate,
      mode:            payMode.selectedOptionValue,
      transaction_ref: payRef.text,
      remarks:         payRemarks.text,
      type:            payType.selectedOptionValue,
      allocations
    };
    storeValue('paymentPayload', payload);
    await apiMakePayment.run();
    closeModal('modalMakePayment');
    await getGRNList.run();
  }
}

export default {
  saveDebitNote: async () => {
    const isItemMode = dnMode.selectedOptionValue === "Item Return";
    let amount = 0;
    let lines = [];

    if (isItemMode) {
      const rawLines = tblDebitLines.tableData;
      lines = rawLines.map(row => {
        const qty     = Number(row.Qty || 0);
        const price   = Number(row.Price || 0);
        const scheme  = Number(row.Sch || 0);
        const discPct = Number(row['Disc %'] || 0);
        const taxPct  = Number(row['GST %'] || 0);
        const gross   = qty * price;
        const discAmt = Math.max(0, gross - scheme) * (discPct / 100);
        const taxable = Math.max(0, gross - scheme - discAmt);
        const taxAmt  = taxable * (taxPct / 100);
        return {
          product_id:  row._product_id, qty, rate: price,
          batch_number: row['Batch No'] || '',
          return_type: row.Reason || 'Damage',
          amount: taxable + taxAmt
        };
      }).filter(l => l.qty > 0);
      amount = lines.reduce((s, l) => s + l.amount, 0);
    } else {
      amount = Number(dnAmount.text);
    }

    if (!amount || amount <= 0) { showAlert('Invalid Amount', 'error'); return; }

    const payload = {
      vendor_id:         appsmith.store.selectedVendor.id,
      amount,
      debit_note_date:   dnDate.selectedDate,
      reason:            dnReason.text,
      linked_invoice_id: selLinkedBill.selectedOptionValue || null,
      lines:             isItemMode ? lines : []
    };
    storeValue('debitNotePayload', payload);
    await apiCreateDebitNote.run();
    closeModal('modalDebitNote');
    await getVendorDebitNotes.run();
  }
}

export default {
  groupByBrand: () => {
    const all = Products.data.data || Products.data || [];
    const grouped = _.groupBy(all, 'brand_name');
    return Object.keys(grouped).map((brandName, index) => {
      const products = grouped[brandName];
      return {
        id: products[0]?.brand_id || index,
        brand_name: brandName,
        product_count: products.length,
        val_stock_taxable: _.sumBy(products, p => Number(p.stock_value_cost || 0)).toFixed(2),
        val_total_bought:  _.sumBy(products, p => Number(p.stock_value_total_bought || 0)).toFixed(2),
        products: products.sort((a, b) => a.product_name.localeCompare(b.product_name))
      };
    }).sort((a, b) => a.brand_name.localeCompare(b.brand_name));
  }
}

