export default {
  savePO: async () => {
    // 1. FILTER INPUTS
    // In Appsmith, we access the store via appsmith.store
    const rawLines = appsmith.store.poLines || [];
    const validLines = rawLines.filter(row => Number(row.Qty) > 0);

    if (validLines.length === 0) {
      showAlert("No items to save!", "error");
      return;
    }

    // Access the selected value from the Select widget
    if (!vendorDropdown.selectedOptionValue) {
      showAlert("Select a Vendor", "error");
      return;
    }

    // 2. PREPARE PAYLOAD
    const dbPayloadLines = validLines.map(row => ({
      product_id: row._product_id,
      ordered_qty: Number(row.Qty),
      mrp: Number(row.MRP),
      price: Number(row.Price),
      scheme_amount: Number(row.Sch || 0),
      discount_percent: Number(row['Disc %'] || 0),
      tax_percent: Number(row['GST %'] || 0)
    }));

    const dbPayload = {
      vendor_id: vendorDropdown.selectedOptionValue,
      remarks: "",
      lines: dbPayloadLines
    };

    // 3. SEND TO SERVER
    // Store the payload so the query can reference it as {{appsmith.store.poPayload}}
    await storeValue('poPayload', dbPayload);

    showAlert("Saving...", "info");

    try {
      // .run() is the Appsmith equivalent to .trigger()
      const result = await submitPO.run();

      // In Appsmith, if the query succeeds, 'result' contains the response data
      if (result) {
        showAlert("PO Saved Successfully!", "success");

        // 7. CLEANUP
        await storeValue('poLines', []);

        // Reset widgets and refresh sequence
        resetWidget('vendorDropdown', true);
        await getNextPO.run();

        // 8. CLOSE MODAL (Drawers are Modals in Appsmith)
        closeModal('drawerCreatePO');
      }
    } catch (error) {
      showAlert("Error saving PO: " + error.message, "error");
    }
  }
}

export default {
  updatePO: async () => {
    console.log("=== STARTING UPDATE ===");

    // 1. GET SOURCE (Appsmith Table data or Store)
    const sourceData = poTable.tableData || appsmith.store.poLines || [];

    // 2. FILTER & MAP (Bulletproof Keys for Parity)
    const validLines = sourceData
      .filter(r => Number(r['Qty'] || r['qty'] || r['ordered_qty'] || 0) > 0)
      .map(r => ({
          product_id:         r._product_id || r.product_id,
          ordered_qty:        Number(r['Qty'] || r['qty'] || r['ordered_qty']),
          mrp:                Number(r['MRP'] || r['mrp']),
          price:              Number(r['Price'] || r['price'] || r['purchase_rate']),
          scheme_amount:      Number(r['Sch'] || r['scheme_amount'] || 0),
          discount_percent:   Number(r['Disc %'] || r['Disc'] || r['discount_percent'] || 0),
          tax_percent:        Number(r['GST %'] || r['tax_percent'] || 5)
      }));

    if (validLines.length === 0) {
      showAlert("No items to save!", "error");
      return;
    }

    // Get vendor details from store as requested
    const vID = Number(appsmith.store.selectedVendorId) || 0;
    if (vID === 0) {
       showAlert("Invalid Vendor ID in Store", "error");
       return;
    }

    // 3. PREPARE PAYLOAD
    const dbPayload = {
        vendor_id:      vID,
        remarks:        "Updated via Appsmith Manager", 
        lines:          validLines
    };

    // 4. SEND TO SERVER
    // Store the payload so the query can access it via {{appsmith.store.poUpdatePayload}}
    await storeValue('poUpdatePayload', dbPayload);

    showAlert("Updating...", "info");

    try {
      // Trigger the REST Query
      const result = await updatePOQuery.run();

      // 5. SUCCESS & CLEANUP
      if (result) {
        showAlert("PO Updated Successfully!", "success");

        // Refresh the PO list
        await getPOs.run(); 

        // UI Cleanup
        closeModal('drawerCreatePO');
        await storeValue('poLines', []);
      }
    } catch (e) {
      showAlert("Update failed: " + e.message, "error");
    }
  }
}

export default {
  getSummary: () => {
    // 1. GET SOURCE (Appsmith Table data)
    const lines = tblViewLines.tableData || [];
    const groups = {};

    // 2. Group by Tax Name
    lines.forEach(row => {
      const taxName = row['Tax Name'] || 'No Tax';
      if (!groups[taxName]) {
        groups[taxName] = { 
          PARTICULARS: taxName, 
          Pcs: 0, 
          Gross: 0, 
          Sch: 0, 
          Disc: 0, 
          Taxable: 0, 
          Tax: 0, 
          Net: 0 
        };
      }

      const g = groups[taxName];
      // Note: Using standard Number() for safety
      g.Pcs     += Number(row['Qty'] || 0);
      g.Gross   += Number(row['Gross'] || 0);
      g.Sch     += Number(row['Sch'] || 0);

      // Using Math.max to avoid negative discounts if Gross is 0
      const rowGross = Number(row['Gross'] || 0);
      g.Disc    += (Number(row['Disc %'] || 0) / 100 * rowGross);

      g.Taxable += Number(row['Taxable'] || 0);

      // Handle Tax Amount Mapping (supporting multiple potential keys for parity)
      const taxAmt = Number(row['GST $'] || row['tax_amount'] || 0);
      g.Tax     += taxAmt;
      g.Net     += Math.round(Number(row['Net $'] || 0));
    });

    // 3. Convert Groups to Array
    const resultRows = Object.values(groups);

    // 4. Calculate Grand Total Row
    // We use .reduce() to sum up every column from our grouped array
    if (resultRows.length > 0) {
      const totalRow = resultRows.reduce((acc, curr) => {
        acc.Pcs     += curr.Pcs;
        acc.Gross   += curr.Gross;
        acc.Sch     += curr.Sch;
        acc.Disc    += curr.Disc;
        acc.Taxable += curr.Taxable;
        acc.Tax     += curr.Tax;
        acc.Net     += curr.Net;
        return acc;
      }, { 
        PARTICULARS: 'Grand Total', 
        Pcs: 0, Gross: 0, Sch: 0, Disc: 0, Taxable: 0, Tax: 0, Net: 0 
      });

      // 5. Append Total Row to the list
      resultRows.push(totalRow);
    }

    return resultRows;
  }
}

export default {
	transformPORows: (data) => {
		const lines = data.lines || [];
		return lines.map((row, i) => {
			const qty = Number(row.ordered_qty || 0);
			const price = Number(row.purchase_rate || row.price || 0);
			const mrp = Number(row.product_mrp || row.mrp || 0);
			const sch = Number(row.scheme_amount || 0);
			const discPct = Number(row.discount_percent || 0);
			const taxPct = Number(row.tax_percent || 5);

			const gross = qty * price;
			const discAmt = (gross - sch) * (discPct / 100);
			const taxable = gross - sch - discAmt;
			const taxAmt = taxable * (taxPct / 100);
			const net = taxable + taxAmt;

			return {
				"S.No": i + 1,
				"EAN Code": row.ean_code || "",
				"Item Name": row.product_name,
				"MRP": mrp,
				"Price": price,
				"Qty": qty,
				"Sch": sch,
				"Disc %": discPct,
				"GST %": taxPct,
				"Gross $": Number(gross.toFixed(2)),
				"Disc. $": Number(discAmt.toFixed(2)),
				"Taxable $": Number(taxable.toFixed(2)),
				"GST $": Number(taxAmt.toFixed(2)),
				"Net $": Number(net.toFixed(2)),
				"Batch No": "",
				"Expiry": null,
				"_product_id": row.product_id
			};
		});
	}
}

export default {
  onPOSelected: async () => {
    // 1. Fetch the PO data using the selected value
    const poId = ChoosePo.selectedOptionValue;
    if (!poId) return;

    const rawData = await getPOForGRN.run({ id: poId });

    // 2. Transform the data using our financial logic
    const transformedLines = JSFilterGRNPo.transformPORows(rawData);

    // 3. Overwrite the table (This creates the "Filtered" effect immediately)
    await storeValue('piLines', transformedLines);

    showAlert("PO Items Applied", "success");
  }
}

export default {
  recalculateRow: async () => {
    // 1. Safety Check: Only proceed if there is actually a change
    const change = GRNTable.updatedRow; // Ensure this matches ONLY your actual Table Name!

    if (!change || !change._product_id) {
       console.log("No valid updatedRow found. Skipping recalculation.");
       return;
    }

    const targetId = change._product_id;
    const currentTable = appsmith.store.piLines || [];

    // 2. Map and Merge
    const updatedData = currentTable.map((row) => {
      // Safety: Match on BOTH hidden ID types
      if (row._product_id !== targetId && row.product_id !== targetId) return row;

      const merged = { ...row, ...change };

      // Math
      const qty = Number(merged.Qty) || 0;
      const price = Number(merged.Price) || 0;
      const sch = Number(merged.Sch) || 0;
      const discPct = Number(merged["Disc %"]) || 0;
      const gstPct = Number(merged["GST %"]) || 5;

      const gross = qty * price;
      const discAmt = (gross - sch) * (discPct / 100);
      const taxable = gross - sch - discAmt;
      const gstAmt = taxable * (gstPct / 100);
      const net = taxable + gstAmt;

      return {
        ...merged,
        "Qty": qty,
        "Price": price,
        "Sch": sch,
        "Disc %": discPct,
        "Gross $": Number(gross.toFixed(2)),
        "Disc. $": Number(discAmt.toFixed(2)),
        "Taxable $": Number(taxable.toFixed(2)),
        "GST $": Number(gstAmt.toFixed(2)),
        "Net $": Number(net.toFixed(2))
      };
    });

    // 3. Save
    await storeValue('piLines', updatedData);
  }
}

