() => {
  const rawResponse = getVendorLedger.data;
  const rawData = Array.isArray(rawResponse) ? rawResponse : rawResponse?.data && Array.isArray(rawResponse.data) ? rawResponse.data : [];
  const emptyResult = {
    opening_balance: 0,
    transactions: [],
    closing_balance: 0
  };
  if (!dateStart.selectedDate || !dateEnd.selectedDate || rawData.length === 0) {
    return emptyResult;
  }
  const start = moment(dateStart.selectedDate).startOf('day');
  const end = moment(dateEnd.selectedDate).endOf('day');
  let openingBalance = 0;
  const filteredTxns = [];
  const sorted = _.sortBy(rawData, ['date', 'created_at']);
  sorted.forEach(txn => {
    const txnDate = moment(txn.date);
    const netChange = (Number(txn.credit_amount) || 0) - (Number(txn.debit_amount) || 0);
    if (txnDate.isBefore(start, 'day')) {
      openingBalance += netChange;
    } else if (txnDate.isSameOrBefore(end, 'day') && txnDate.isSameOrAfter(start, 'day')) {
      filteredTxns.push({
        ...txn,
        net_change: netChange
      });
    }
  });
  let running = openingBalance;
  const finalData = filteredTxns.map(t => {
    running += t.net_change;
    return {
      ...t,
      running_balance: Number(running.toFixed(2))
    };
  });
  return {
    opening_balance: Number(openingBalance.toFixed(2)),
    transactions: finalData,
    closing_balance: Number(running.toFixed(2))
  };
}

async () => {
  const vendor = appsmith.store.selectedVendor;
  const totalAmount = Number(payAmount.text || 0);
  const mode = payMode.selectedOptionValue;
  const type = payType.selectedOptionValue;
  const isRefund = type === 'REFUND';
  if (!totalAmount || totalAmount <= 0) {
    return showAlert("Please enter a valid amount", "error");
  }
  let allocations = [];
  if (!isRefund) {
    const selectedBills = tblPendingBills.selectedRows || [];
    if (selectedBills.length > 0) {
      let remaining = totalAmount;
      for (const bill of selectedBills) {
        if (remaining <= 0) break;
        const balance = Number(bill.balance || bill['Balance $'] || 0);
        const alloc = Math.min(balance, remaining);
        if (alloc > 0) {
          allocations.push({
            invoice_id: bill.id,
            amount: Number(alloc.toFixed(2))
          });
          remaining -= alloc;
        }
      }
    }
  }
  const payload = {
    vendor_id: Number(vendor.id),
    amount: totalAmount,
    payment_date: moment(payDate.selectedDate).format("YYYY-MM-DD"),
    mode: mode,
    transaction_type: type,
    remarks: payRemarks.text,
    bank_account_id: selPaymentBank.selectedOptionValue,
    allocations: isRefund ? [] : allocations,
    transaction_ref: mode === 'Online' ? selBankRefVendor.selectedOptionLabel : mode === 'Cheque' ? payChqNo.text : payRef.text,
    bank_statement_entry_id: mode === 'Online' ? selBankRefVendor.selectedOptionValue : null,
    cheque_no: payChqNo.text,
    cheque_date: payChqDate.selectedDate ? moment(payChqDate.selectedDate).format("YYYY-MM-DD") : null,
    bank_name: payChqBank.selectedOptionValue
  };
  try {
    await apiMakePayment.run({
      payload
    });
    closeModal('modalMakePayment');
    showAlert("Payment Recorded Successfully", "success");
    showModal(drawerVendorProfile.name);
    await Promise.all([getVendorLedger.run(), q_getUnconsumedDebits.run()]);
  } catch (e) {
    showAlert("Error processing payment: " + e.message, "error");
  }
}

