export default {
  getDNTaxSummary: () => {
    // 1. Read from the API response (ensure the name matches your query)
    const lines = getDebitNoteLines.data || [];
    const groups = {};

    lines.forEach(row => {
      // Group by GST % string (e.g., "18.00")
      const gstPct = row['GST %'] || "0.00";
      const taxName = gstPct + '% GST';

      if (!groups[taxName]) {
        groups[taxName] = { 
          PARTICULARS: taxName, 
          Pcs: 0, Gross: 0, Sch: 0, Disc: 0, 
          Taxable: 0, Tax: 0, Net: 0 
        };
      }

      const g = groups[taxName];
      g.Pcs     += Number(row['Qty'] || 0);
      g.Gross   += Number(row['Gross $'] || 0);
      g.Sch     += Number(row['Sch'] || 0);
      g.Disc    += Number(row['Disc. $'] || 0); // Uses 'Disc. $' from your JSON
      g.Taxable += Number(row['Taxable $'] || 0);
      g.Tax     += Number(row['GST $'] || 0);
      g.Net     += Number(row['Net $'] || 0);
    });

    const resultRows = Object.values(groups);

    // 2. Add Grand Total Row
    if (resultRows.length > 0) {
      const totalRow = resultRows.reduce((acc, curr) => {
        acc.Pcs     += curr.Pcs;
        acc.Gross   += curr.Gross;
        acc.Sch     += curr.Sch;
        acc.Disc    += curr.Disc;
        acc.Taxable += curr.Taxable;
        acc.Tax     += curr.Tax;
        acc.Net     += curr.Net;
        return acc;
      }, { PARTICULARS: 'Total', Pcs: 0, Gross: 0, Sch: 0, Disc: 0, Taxable: 0, Tax: 0, Net: 0 });

      resultRows.push(totalRow);
    }

    // 3. Final Rounding to 2 Decimals
    return resultRows.map(row => ({
      ...row,
      Gross: Number(row.Gross.toFixed(2)),
      Disc: Number(row.Disc.toFixed(2)),
      Taxable: Number(row.Taxable.toFixed(2)),
      Tax: Number(row.Tax.toFixed(2)),
      Net: Number(row.Net.toFixed(2))
    }));
  }
}

export default {
  populateDebitLines: async () => {
    const vID = SelectVendor.selectedOptionValue; 
    // Assuming your Multi-Select widget is named MultiSelectStatus
    const selectedStatuses = MultiSelectStatus.selectedOptionValues; 

    if (!vID || !selectedStatuses || selectedStatuses.length === 0) {
      showAlert("Please select a Vendor and at least one Return Reason (Good/Expiry/Damage)", "warning");
      return;
    }

    // 1. Fetch Global Batches & Products
    // I assume getBatch.run() returns the full list you showed me
    const allBatches = await getBatch.run(); 
    const rawData = Products.data.data; 
    const allProducts = Array.isArray(rawData) ? rawData : (rawData?.data || []);

    // 2. Filter Batches
    // Rule: Must have stock (>0) AND status must match the user's checkbox selection
    const eligibleBatches = allBatches.filter(b => 
      Number(b.quantity_remaining) > 0 && 
      selectedStatuses.includes(b.status)
    );

    // 3. Map Batches to Table Rows (One row per Batch)
    const tableData = eligibleBatches.map((batch, index) => {
      // Find the parent product to get the Name, EAN, and Tax info
      const p = allProducts.find(prod => String(prod.id) === String(batch.product_id));

      // If the product doesn't belong to this vendor (if your Products query is vendor-filtered), skip it
      if (!p) return null;

      const qty = Number(batch.quantity_remaining);
      const price = Number(batch.purchase_rate || 0);
      const gstPct = Number(p.tax_percentage || 0);

      // Calculate initial totals for the pre-filled quantity
      const gross = qty * price;
      const taxable = gross; // Starting with 0 discount/scheme
      const gstAmt = taxable * (gstPct / 100);
      const net = taxable + gstAmt;

      return {
        "_row_id": batch.id + "_" + Math.random().toString(36).substr(2, 9),
        "S.No": index + 1,
        "EAN Code": p.ean_code || "",
        "Item Name": p.product_name,
        "MRP": Number(batch.mrp || 0),
        "Price": price,
        "Qty": qty, // PRE-FILLED with available stock
        "Sch": 0,
        "Disc %": 0,
        "GST %": gstPct, 
        "Gross $": Number(gross.toFixed(2)),
        "Disc. $": 0,
        "Taxable $": Number(taxable.toFixed(2)),
        "GST $": Number(gstAmt.toFixed(2)),
        "Net $": Number(net.toFixed(2)), 
        "Reason": batch.status, // Uses "Good", "Expiry", or "Damage"
        "Batch No": batch.batch_code, 
        "Expiry": batch.expiry_date,
        "_product_id": p.id,
        // Stashing all batches for this product in case they want to switch manually later
        "_batches": allBatches.filter(b => String(b.product_id) === String(p.id)) 
      };
    }).filter(row => row !== null); // Remove any nulls if product wasn't found

    // 4. Update the store
    storeValue('GlobalDebitLinesData', tableData); 
    return tableData;
  }
}

export default {
  updateDebitRow: () => {
    const change = tblDebitLines.updatedRow; 
    const targetIndex = tblDebitLines.updatedRowIndex; // Standard Appsmith property

    if (targetIndex === undefined || targetIndex === -1) {
      console.error("Could not determine the updated row index.");
      return;
    }

    const currentData = appsmith.store.GlobalDebitLinesData || [];
    let newData = [...currentData];

    // Merge the changes into the row at the specific index
    let row = { ...newData[targetIndex], ...change };

    console.log("Updating row at index:", targetIndex, "Changes:", change);

    // --- [BATCH AUTO-FILL LOGIC] --- (Exact same as your original)
    if (change["Batch No"]) {
      const selectedBatch = (row._batches || []).find(b => b.batch_code === change["Batch No"]);
      if (selectedBatch) {
        row["Expiry"] = selectedBatch.expiry_date || "No Expiry";
        row["MRP"] = Number(selectedBatch.mrp || 0);
        row["Price"] = Number(selectedBatch.purchase_rate || 0);
      }
    }

    // --- [CALCULATION LOGIC] --- (Exact same as your original)
    const Qty = Number(row['Qty'] || 0);
    const Price = Number(row['Price'] || 0);    
    const Sch = Number(row['Sch'] || 0);
    const DiscPct = Number(row['Disc %'] || 0);
    const GstPct = Number(row['GST %'] || 0);

    const Gross = Qty * Price;
    const DiscAmt = (Gross - Sch) * (DiscPct / 100);
    const Taxable = Math.max(0, Gross - Sch - DiscAmt);
    const GstAmt = Taxable * (GstPct / 100);
    const Net = Taxable + GstAmt;

    // Update Result Columns
    row['Gross $'] = Number(Gross.toFixed(2));
    row['Disc. $'] = Number(DiscAmt.toFixed(2));
    row['Taxable $'] = Number(Taxable.toFixed(2));
    row['GST $'] = Number(GstAmt.toFixed(2));
    row['Net $'] = Number(Net.toFixed(2));

    newData[targetIndex] = row;
    storeValue('GlobalDebitLinesData', newData);

    console.log("Store Updated Successfully.");
    return newData;
  }

}

export default {
    createDebitNote: async () => {
        // 1. Setup metadata
        const noteType = selNoteType.selectedOptionValue; // "Debit Note" or "Return Slip"
        const isItemMode = selDNMode.selectedOptionValue === "Item Return";
        let amount = 0;
        let lines = [];

        if (isItemMode) {
            // Source from the storage variable used by the table
            const rawLines = appsmith.store.GlobalDebitLinesData || [];

            lines = rawLines.map(row => {
                const qty = Number(row['Qty'] || 0);
                const price = Number(row['Price'] || 0);    
                const scheme = Number(row['Sch'] || 0);
                const discPct = Number(row['Disc %'] || 0);
                const taxPct = Number(row['GST %'] || 0);

                // --- Exact Replica Math ---
                const gross = qty * price;
                const valForDisc = Math.max(0, gross - scheme);
                const discAmt = valForDisc * (discPct / 100);
                const taxable = Math.max(0, gross - scheme - discAmt);
                const taxAmt = taxable * (taxPct / 100);
                const total = taxable + taxAmt;

                return {
                    product_id: row._product_id,
                    qty: qty,
                    rate: price,
                    batch_number: row['Batch No'] || "",
                    return_type: row.Reason || "Damage",
                    amount: Number(total.toFixed(2)),       
                    tax_amount: Number(taxAmt.toFixed(2))   
                };
            }).filter(l => l.qty > 0);

            amount = _.sumBy(lines, 'amount');
        } else {
            amount = Number(inpDNAmount.value || 0);
        }

        // 2. Validation
        if (!amount || amount <= 0) {
            showAlert("Invalid Amount. Please check your items.", "error");
            return;
        }

        // 3. Trigger API with Payload
        const payload = {
            vendor_id: SelectVendor.selectedOptionValue,
            amount: amount,
            debit_note_date: moment(dtPckDN.selectedDate).format("YYYY-MM-DD"),
            reason: inpDNReason.text,
            linked_invoice_id: selLinkedBill.selectedOptionValue || null,
            note_type: noteType, // PASSING THE TYPE
            lines: isItemMode ? lines : [] 
        };

        try {
            const response = await apiCreateDebitNote.run({ payload });

            // Dynamic Success Message
            const msgLabel = noteType === 'Return Slip' ? 'Return Slip' : 'Debit Note';
            showAlert(`${msgLabel} Created: ${response.debit_note_number}`, "success");

            // Post-save actions
            storeValue('lastDNNumber', response.debit_note_number);
            closeModal(modalDebitNote.name);
            getDebitNotes.run();

        } catch (error) {
            showAlert("Error: " + error.message, "error");
        }
    }
}

export default {
    convertToDN: async () => {
        // 1. Validation
        if (!debiteNotetbl.triggeredRow?.id) {
            return showAlert("No Return Slip selected.", "warning");
        }

        try {
            // 2. Execute API
            const response = await apiConvertRSToDN.run({ 
                id: debiteNotetbl.triggeredRow.id 
            });

            // 3. Extract DN Number for the alert
            const dnData = response?.data || response;
            const newDN = dnData?.debit_note_number || "New DN";

            showAlert(`Converted Successfully! New DN: ${newDN}`, "success");

            // 4. THE CLEANUP
            // Close the modal and refresh the background data simultaneously
            closeModal('modalFrameDebitNote'); 
            await getDebitNotes.run();

        } catch (error) {
            showAlert("Conversion Failed: " + (error?.message || "Unknown Error"), "error");
        }
    }
}

export default {
	previewDebitNote: async (dnHeader) => {
		try {
			if (!dnHeader || !dnHeader.id) throw new Error("No Debit Note data selected.");

			// --- 1. LIBRARY SAFETY ---
			if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
			const jsPDFConstructor = jspdf.jsPDF || jspdf;
			const doc = new jsPDFConstructor('p', 'pt', 'a4');

			if (typeof doc.autoTable !== "function" && jspdf.plugin && jspdf.plugin.autotable) {
				jsPDFConstructor.API.autoTable = jspdf.plugin.autotable;
			}

			// --- 2. PREPARE DATA ---
			const dnLines = getDebitNoteLines.data || [];
			const summaryData = this.getDNTaxSummary(dnLines);
			const grandTotal = Number(dnHeader.amount || 0);
			const brand = Global_Assets.getSummary();
			const margin = 20; 
			const pageWidth = doc.internal.pageSize.width;
			const pageHeight = doc.internal.pageSize.height;

			// --- HELPER: DRAW RECURRING HEADER ---
			const drawMainHeader = (currentPage, totalPages) => {
				const headerY = margin;
				try {
					const logo = Global_Assets.getLogo();
					if (logo && logo.startsWith("data:image/")) {
						doc.addImage(logo, 'PNG', margin, headerY, 90, 30);
					}
				} catch (e) { console.error("Logo error", e); }

				doc.setTextColor(0, 0, 0);
				doc.setFont("helvetica", "bold"); doc.setFontSize(16);
				const title = (dnHeader.note_type || "DEBIT NOTE").toUpperCase();
				doc.text(title, pageWidth / 2, headerY + 15, { align: "center" });

				doc.setFontSize(11); doc.setFont("helvetica", "normal");
				doc.text(String(dnHeader.debit_note_number), pageWidth / 2, headerY + 30, { align: "center" });

				const boxesY = headerY + 45;
				const gap = 8;
				const boxWidth = (pageWidth - (margin * 2) - (gap * 2)) / 3;
				const boxHeight = 90;

				this._drawSimpleBox(doc, margin, boxesY, boxWidth, boxHeight, [
					["DN NUMBER", String(dnHeader.debit_note_number)],
					["DATE", moment(dnHeader.debit_note_date).format("DD/MM/YYYY")],
					["LINKED INV", String(dnHeader.linked_invoice_number || "-")],
					["TOTAL AMT", "INR " + Number(grandTotal).toFixed(2)],
					["PAGE", `${currentPage} / ${totalPages}`]
				]);

				this._drawSimpleBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, [
					["From", String(brand.regt_name)],
					["Address", String(brand.address)],
					["GST", String(brand.gst)],
					["Contact", String(brand.contact_no)],
					["Email", String(brand.email)]
				]);

				const vAddr = [dnHeader.vendor_address, dnHeader.vendor_city, dnHeader.vendor_pin].filter(Boolean).join(", ");
				this._drawSimpleBox(doc, margin + (boxWidth * 2) + (gap * 2), boxesY, boxWidth, boxHeight, [
					["Vendor", String(dnHeader.vendor_name)],
					["Address", vAddr || "-"],
					["GST", String(dnHeader.vendor_gst || "-")],
					["Contact", String(dnHeader.vendor_contact || "-")],
					["Place of Supply", String(dnHeader.place_of_supply || "-")]
				]);

				return boxesY + boxHeight + 15;
			};

			// --- 3. ITEMS TABLE ---
			doc.autoTable({
				startY: 160,
				margin: { left: margin, right: margin, top: 160, bottom: 120 },
				head: [["S.N", "ITEM NAME", "CODE / EAN", "HSN", "BATCH / EXP", "MRP", "QTY", "PRICE", "TXBL", "GST%", "GST$", "NET$"]],
				body: dnLines.map((row, index) => {
					const expiryStr = row['Expiry'] ? moment(row['Expiry']).format("MM/YY") : "-";
					return [
						index + 1, row['Item Name'], `${row['product_code'] || ""}\n${row['EAN Code'] || ""}`, 
						row['hsn_code'] || "-", `${row['Batch No'] || ""}\n${expiryStr}`,
						Number(row['MRP'] || 0).toFixed(2), row['Qty'], Number(row['Price'] || 0).toFixed(2),
						Number(row['Taxable $'] || 0).toFixed(2), row['GST %'] + "%",
						Number(row['GST $'] || 0).toFixed(2), Number(row['Net $'] || 0).toFixed(2)
					];
				}),
				didDrawPage: (data) => {
					drawMainHeader(data.pageNumber, doc.internal.getNumberOfPages());
				},
				theme: 'grid',
				styles: { fontSize: 7, cellPadding: 3, lineColor: [100, 100, 100], lineWidth: 0.5, textColor: [0, 0, 0] },
				headStyles: { fillColor: [240, 240, 240], textColor: [0, 0, 0], fontStyle: 'bold' },
				columnStyles: {
					0: { cellWidth: 20 }, 1: { cellWidth: 'auto', minCellWidth: 100 },
					2: { cellWidth: 55 }, 4: { cellWidth: 55 },
					5: { halign: 'right' }, 6: { halign: 'center' }, 7: { halign: 'right' },
					8: { halign: 'right' }, 9: { halign: 'center' }, 10: { halign: 'right' }, 11: { halign: 'right' }
				}
			});

			// --- 4. FOOTER & SUMMARY ---
			let currentY = doc.lastAutoTable.finalY + 15;

			// If summary won't fit on this page, add a new page
			if (currentY > pageHeight - 220) {
				doc.addPage();
				currentY = 160; 
			}

			doc.autoTable({
				startY: currentY,
				margin: { left: margin },
				head: [["TAX SUMMARY", "TOTAL PCS", "TAXABLE VALUE", "TAX AMOUNT", "NET AMOUNT"]],
				body: summaryData.map(row => [
					row.PARTICULARS, row.Pcs, row.Taxable.toFixed(2), row.Tax.toFixed(2), row.Net.toFixed(2)
				]),
				didDrawPage: (data) => {
					// IMPORTANT: This ensures the header is drawn on Page 2 as well
					drawMainHeader(data.pageNumber, doc.internal.getNumberOfPages());
				},
				theme: 'grid',
				styles: { fontSize: 8, cellPadding: 4, lineColor: [0, 0, 0], lineWidth: 0.5, textColor: [0, 0, 0] },
				headStyles: { fillColor: [245, 245, 245], fontStyle: 'bold' },
				bodyStyles: (row) => (row.at(0) === 'Total' ? { fontStyle: 'bold', fillColor: [250, 250, 250] } : {}),
				tableWidth: 400
			});

			const wordsY = doc.lastAutoTable.finalY + 25;
			doc.setFontSize(10); doc.setFont("helvetica", "bold");
			doc.text("Total Amount (in words):", margin, wordsY);
			doc.setFont("helvetica", "normal");
			doc.text(this.toWords(Math.round(grandTotal)), margin + 120, wordsY);

			doc.setFontSize(8);
			doc.text("This is a computer generated document and does not require a physical signature.", margin, wordsY + 20);

			// Acknowledgement Slip
			const slipY = pageHeight - 100;
			doc.setLineDash([3, 3], 0); doc.line(margin, slipY, pageWidth - margin, slipY); doc.setLineDash([], 0);
			doc.setFontSize(9); doc.setFont("helvetica", "bold");
