export default {
    analyzeDemand: () => {
        // 1. Debugging Inputs
        // Make sure your tblSalesOrders widget has "Enable multi-row selection" turned ON
        const selectedOrders = tblSalesOrders.selectedRows || [];
        const allProducts = getProducts.data.data || getProducts.data || [];

        // Appsmith uses the global 'store' for state variables
        const transitMap = appsmith.store.varTransitStock || {};

        console.log("Debug: Processing", selectedOrders.length, "orders");
        console.log("Debug: All Products (First Entry):", allProducts[0]);

        if (selectedOrders.length === 0) {
            showAlert("Please select at least one order.", "warning");
            return;
        }

        // 2. Aggregate Demand
        let demandMap = {}; 
        selectedOrders.forEach(order => {
            // Sometimes Appsmith stores nested JSON as strings. Parse it if necessary.
            let lines = [];
            try {
                lines = typeof order.lines === 'string' ? JSON.parse(order.lines) : (order.lines || []);
            } catch(e) {
                console.error("Error parsing order lines", e);
            }

            lines.forEach(line => {
                // FORCE STRING for comparison safety
                const pid = String(line.product_id); 
                if (!demandMap[pid]) {
                    demandMap[pid] = { 
                        item_id: pid, 
                        product_name: line.product_name, 
                        demand: 0,
                        master_rate: Number(line.rate || 0) 
                    };
                }
                demandMap[pid].demand += Number(line.qty || line.ordered_qty || 0); // Handle 'qty' or 'ordered_qty'
            });
        });

        // 3. Compare (Real DB + Temp Variable)
        const analysis = Object.values(demandMap).map(item => {
            // TYPE SAFE FIND: Compare as Strings
            const product = allProducts.find(p => String(p.id) === String(item.item_id));

            if (!product) console.warn("Could not find product details for ID:", item.item_id);

            const realStock = Number(product.current_stock || 0);
            const transitEntry = transitMap[item.item_id] || {};
            const transitQty = Number(transitEntry.qty || 0);

            const totalAvail = realStock + transitQty;
            const shortage = Math.max(0, item.demand - totalAvail);

            return {
                ...item,
                real_stock: realStock,
                transit_qty: transitQty,
                temp_batch: transitEntry.batch_code || '-',
                total_avail: totalAvail,
                shortage: shortage,
                status: shortage > 0 ? "SHORT" : "OK",
                // Prices from Master Table (Null check)
                mrp: Number(product.mrp || 0),
                distributor_rate: Number(product?.distributor_rate || 0),
                wholesale_rate: Number(product?.wholesale_rate || 0),
                dealer_rate: Number(product?.dealer_rate || 0),
                retail_rate: Number(product?.retail_rate || 0),
                rate: item.master_rate 
            };
        });

        // 4. Update and Open Modal
        // Appsmith global store takes a key and a value
        storeValue('varDemandAnalysis', analysis);

        // Show the Appsmith Modal widget
        showModal('modalStockAllocation');
    }
}

export default {
    generateBulkInvoices: async () => {
        // Appsmith gives you the full array of selected rows. Map them to extract just the ID.
        // Make sure 'id' matches the primary key column name in your table!
        const selectedRows = tblSalesOrders.selectedRows || [];
        const selectedIDs = selectedRows.map(row => row.id); 

        // Get state variable from the Appsmith store
        const transitData = appsmith.store.varTransitStock || {};

        if (!selectedIDs || selectedIDs.length === 0) {
             showAlert("No orders selected.", "warning");
             return;
        }

        try {
            // Trigger Backend - Pass variables directly into the run() function
            // Note: Inside the actual API widget body, you MUST reference these 
            // values using {{this.params.order_ids}} and {{this.params.transit_stock}}
            const data = await apiBulkInvoiceGenerate.run({
                order_ids: selectedIDs,
                transit_stock: transitData, 
                allow_negative_stock: true
            });

            // --- On Success ---
            closeModal('modalStockAllocation');
            showAlert(`Generated ${data.invoices ? data.invoices.length : 'multiple'} Invoices`, "success");

            // Cleanup actions
            await getSalesOrder.run();  
            storeValue('varTransitStock', {}); 
            storeValue('varDemandAnalysis', []); 

        } catch (err) {
            // --- On Failure ---
            showAlert("Error: " + (err.message || "Failed to generate invoices"), "error");
        }
    }
}

export default {
    openTransitEntry: () => {
        // 1. Get selected rows
        // Appsmith gives us the full row objects directly from selectedRows
        const rows = tblAllocation.selectedRows || [];

        if (rows.length === 0) {
            showAlert("Please select at least one item to allocate transit stock.", "warning");
            return;
        }

        // 2. Map to Table Rows (incorporate existing session data if any)
        const currentStock = appsmith.store.varTransitStock || {};

        const tableRows = rows.map(r => {
            const pid = String(r.item_id || r.id);
            const saved = currentStock[pid] || {};

            return {
                item_id: pid,
                product_name: r.product_name,
                ordered_qty: Number(r.ordered_qty || 0),
                shortfall_qty: Number(r.shortfall_qty || 0),
                qty: saved.qty !== undefined ? saved.qty : Number(r.shortfall_qty || 0),
                batch_code: saved.batch_code || 'TRANSIT-PENDING',
                rate: saved.rate !== undefined ? saved.rate : Number(r.rate || 0)
            };
        });

        // 3. Set the table variable
        storeValue('varTransitTableData', tableRows); 

    }
}

export default {
  syncTransitEntry: async () => {
    // 1. Get Changes from Appsmith Table (updatedRows contains the edited cells)
    const changes = tblTransitEntry.updatedRows || [];
    if (changes.length === 0) return;

    // 2. Access Appsmith Store (equivalent to Retool Variables)
    // Assuming your data is stored in the Appsmith store
    let newTableData = _.cloneDeep(appsmith.store.varTransitTableData || []);
    let sessionMap = _.cloneDeep(appsmith.store.varTransitStock || {});

    // 3. Process Changes
    changes.forEach(change => {
      // Appsmith 'updatedRows' structure: { "0": { "qty": 10 }, "1": { "rate": 50 } }
      // The key is the row index. 'change.allRowData' gives the full row.
      const updatedRowData = change.allFields;
      const pid = String(updatedRowData.item_id);

      // Find row in our local copy
      const targetIndex = newTableData.findIndex(row => String(row.item_id) === pid);

      if (targetIndex !== -1) {
        // A. Update the specific row
        newTableData[targetIndex] = { ...newTableData[targetIndex], ...updatedRowData };

        // B. Sync to Global Session Map
        const finalRow = newTableData[targetIndex];
        sessionMap[pid] = {
          qty: Number(finalRow.qty),
          batch_code: finalRow.batch_code,
          rate: Number(finalRow.rate)
        };
      }
    });

    // 4. Commit Changes to Appsmith Store
    // 'true' as the second argument ensures the store persists across sessions
    await storeValue("varTransitTableData", newTableData);
    await storeValue("varTransitStock", sessionMap);

    // 5. Cleanup UI Markers 
    // In Appsmith, resetting the table data property usually clears "dirty" cells
    resetWidget("tblTransitEntry", true);

    showAlert(`Updated ${changes.length} line(s)`, "info");
  }
}

export default {
    // ... your analyzeDemand code ...

    getProductBreakup: () => {
        const selectedProduct = tblAllocation.triggeredRow; 
        const allOrders = tblSalesOrders.selectedRows || [];

        if (!selectedProduct || !selectedProduct.item_id) {
            showAlert("Please select a product row first.", "warning");
            return;
        }

        const targetId = String(selectedProduct.item_id);

        const breakup = allOrders.reduce((acc, order) => {
            let lines = [];
            try {
                // Defensive check for the 'lines' structure
                lines = typeof order.lines === 'string' ? JSON.parse(order.lines) : (order.lines || []);
            } catch(e) { 
                return acc; 
            }

            const productLine = lines.find(l => String(l.product_id) === targetId);

            if (productLine) {
                acc.push({
                    so_number: order.so_number,
                    customer_name: order.customer_name,
                    route: order.route_name,
                    dse_name: order.dse_name,
                    qty: Number(productLine.qty || 0),
                    rate: productLine.rate,
                    amount: productLine.amount
                });
            }
            return acc;
        }, []);

        // 1. Save the filtered results to the Appsmith Store
        storeValue('varProductBreakup', breakup);

        // 2. Open the modal
        showModal('mdlBreakup');
    }
}

