export default {
	// --- A. DATA FORMATTER (Current code) ---
	getCombinedInvoices: () => {
		// Note: No 'await' here because this is for the Table's 'Table Data' property
		const currentTripInvoices = (getDeliveryList.data || {}).items || []; // items property from /manifest-web
		const pendingInvoices = getPendingInvoices.data || [];

		const assignedIds = currentTripInvoices.map(i => String(i.invoice_id));
		const availablePending = pendingInvoices.filter(i => !assignedIds.includes(String(i.id)));

		return [
			...currentTripInvoices.map(i => ({
				id: i.invoice_id,
				invoice_number: i.invoice_number,
				customer_name: i.customer_name,
				grand_total: i.grand_total,
				current_status: "Assigned to Trip"
			})),
			...availablePending.map(i => ({
				id: i.id,
				invoice_number: i.invoice_number,
				customer_name: i.customer_name,
				grand_total: i.grand_total,
				current_status: "Available (Pending)"
			}))
		];
	},

	// --- B. THE BUTTON TRIGGER (New code) ---
	prepareEditMode: async () => {
		try {
			// 1. Refresh both lists first
			await getDeliveryList.run();
			await getPendingInvoices.run();

			// 2. ONLY once the data is loaded, turn on the Edit mode
			await storeValue('isTripEditActive', true);

			showAlert('Edit Mode Active', 'info');
		} catch (error) {
			showAlert("Failed to load edit mode: " + error.message, "error");
		}
	}
}

export default {
  // 1. Run this when you click "View Details" to initialize the tables
 // In your JS Object (e.g., SyncManager)
initSyncDetails: async () => {
  const details = getSyncDetails.data;

  // Safety check: if there is no data, return empty lists
  if (!details) return { manifest: [], returns: [] };

  const manifest = (details.manifest || []).map(r => ({ 
    ...r, 
    colVerification: 'Approved' 
  }));

  const returns = (details.returns || []).map(r => ({ 
    ...r, 
    colReturnStatus: 'Approved' 
  }));

  // Store them for editing
  await storeValue('manifestData', manifest);
  await storeValue('returnsData', returns);

  // 💡 Adding this return fixes the error you are seeing!
  return { manifest, returns };
},

  // 2. Run this in the Manifest Table's "onSave" or "onCellChange"
  handleManifestEdit: (updatedRow, index) => {
    let data = appsmith.store.manifestData;
    data[index] = updatedRow;
    storeValue('manifestData', data);
  },

  // 3. Run this in the Returns Table's "onSave" or "onCellChange"
  handleReturnEdit: (updatedRow, index) => {
    let data = appsmith.store.returnsData;
    data[index] = updatedRow;
    storeValue('returnsData', data);
  },

  // 4. Final Settle Logic
  settle: async () => {
    // Format the payload for the API
    const payload = {
      sync_id: tblSyncLogs.triggeredRow.id,
      manifest_verifications: appsmith.store.manifestData.map(r => ({
        invoice_id: r.invoice_id,
        status: r.colVerification
      })),
      return_verifications: appsmith.store.returnsData.map(r => ({
        return_id: r.id,
        status: r.colReturnStatus
      })),
      verified_by: getMe.data.id
    };

    // Run the API
    try {
      await settleSyncAPI.run(payload);
      showAlert('All verifications saved!', 'success');
      getSyncLogs.run(); // Refresh list
      closeModal('mdlVerification');
    } catch (e) {
      showAlert('Save failed: ' + e.message, 'error');
    }
  }
}

export default {
	// --- MAIN TRIGGER FUNCTION ---
	downloadTripReports: async (type) => {
		if (type === "PICKLIST") {
			await getPickList.run();

			if (!getPickList.data || !getPickList.data.trip_info) {
			    return showAlert("Failed to generate Picklist. Check API.", "error");
			}

			const tripInfo = {
				trip_number: getPickList.data.trip_info.trip_number || "-",
				date: getPickList.data.trip_info.date || new Date(),
				vehicle_number: getPickList.data.trip_info.vehicle_number || "Not Assigned",
				driver_name: getPickList.data.trip_info.driver_name || "Unassigned",
				team: getPickList.data.trip_info.team_name || "General Team"
			};

			this.generatePickList(getPickList.data.items || [], tripInfo);

		} else if (type === "DELIVERY_LIST") {
			await getDeliveryList.run();

            if (!getDeliveryList.data || !getDeliveryList.data.trip_info) {
			    return showAlert("Failed to generate Delivery List. Check API.", "error");
			}

			const tripInfo = {
				trip_number: getDeliveryList.data.trip_info.trip_number || "-",
				date: getDeliveryList.data.trip_info.date || new Date(),
				vehicle_number: getDeliveryList.data.trip_info.vehicle_number || "Not Assigned",
				driver_name: getDeliveryList.data.trip_info.driver_name || "Unassigned",
				team: getDeliveryList.data.trip_info.team_name || "General Team"
			};

			this.generateDeliveryList(getDeliveryList.data.items || [], tripInfo);
		}
	},

	// --- 1. PICKLIST (PORTRAIT - B&W) ---
	generatePickList: async (data, tripInfo) => {
		try {
			if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
			const jsPDFConstructor = jspdf.jsPDF || jspdf;
			const doc = new jsPDFConstructor('p', 'pt', 'a4'); 

			const brand = Global_Assets.getSummary(); 
			const margin = 15; 
			const pageWidth = doc.internal.pageSize.width;
			const pageHeight = doc.internal.pageSize.height;

			// --- HEADER BLOCK (Page 1 Only) ---
			const drawTopSection = () => {
				const headerY = margin + 5;
				try {
					const logo = Global_Assets.getLogo();
					if (logo && logo.startsWith("data:image/")) {
						doc.addImage(logo, 'PNG', margin, headerY, 80, 25);
					}
				} catch(e) {}

				doc.setTextColor(0, 0, 0); // Black
				doc.setFont("helvetica", "bold");
				doc.setFontSize(14);
				doc.text("WAREHOUSE PICKLIST", pageWidth / 2, headerY + 15, { align: "center" });

				const boxesY = headerY + 35;
				const gap = 10; 
				const boxWidth = (pageWidth - (margin * 2) - (gap * 2)) / 3;
				const boxHeight = 55; 

                // BOX 1: Company
				this._drawSimpleBox(doc, margin, boxesY, boxWidth, boxHeight, [
					["COMPANY", String(brand.regt_name)],
					["GST", String(brand.gst)],
					["CONTACT", String(brand.contact_no)],
					["EMAIL", String(brand.email)]
				]);

                // BOX 2: Trip Details
				this._drawSimpleBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, [
					["TEAM", String(tripInfo.team)],
					["DRIVER", String(tripInfo.driver_name)],
					["VEHICLE", String(tripInfo.vehicle_number)]
				]);

                // BOX 3: Item Metrics
				const totalQty = data.reduce((sum, r) => sum + Number(r.total_qty || 0), 0);
				this._drawSimpleBox(doc, margin + (boxWidth * 2) + (gap * 2), boxesY, boxWidth, boxHeight, [
					["TRIP NO", String(tripInfo.trip_number)],
					["DATE", moment(tripInfo.date).format("DD MMM YYYY")],
					["TOTAL ITEMS", `${data.length} Products`],
					["TOTAL QTY", `${totalQty.toFixed(0)} Units`]
				]);

				return boxesY + boxHeight + 2.5; 
			};

			const firstPageTableStart = drawTopSection();

            // --- TABLE ---
			doc.autoTable({
				startY: firstPageTableStart,
				margin: { left: margin, right: margin, bottom: 40, top: 2.5 },
				head: [["S.N", "CODE", "ITEM DESCRIPTION", "BATCHES", "MRP", "QTY", "LOADED [ ]"]],
				body: data.map((row, index) => [
					index + 1,
					row.product_code || "-",
					{ content: row.product_name || "-", styles: { fontStyle: 'bold' } },
					row.batches || "-",
					Number(row.mrp || 0).toFixed(2),
