export default {
  // --- Initialization Option A: From Catalog (Pre-fill with all products) ---
  loadAllProducts: async () => {
    const allBatches = await getBatch.run();
    const products = getProducts.data.data || [];

    const customerId = selCustomer.selectedOptionValue;
    const customers = getCustomers.data || [];
    const customer = customers.find(c => String(c.id) === String(customerId)) || {};

    let exceptions = [];
    try {
      if (customer.pricing_ex) {
        exceptions = typeof customer.pricing_ex === 'string'
          ? JSON.parse(customer.pricing_ex)
          : customer.pricing_ex;
      }
    } catch (e) {}

    const resolveProductPrice = (item, brandId) => {
      let rateCol = customer.default_price_col || 'dealer_rate';
      if (Array.isArray(exceptions)) {
        const brandEx = exceptions.find(ex => String(ex.brand_id) === String(brandId));
        if (brandEx && brandEx.price_column) {
          rateCol = brandEx.price_column;
        }
      }
      let price = Number(item[rateCol] || 0);
      if (!price) {
        price = Number(item.dealer_rate || 0);
      }
      if (!price) {
        price = Number(item.mrp || 0);
      }
      return price;
    };

    const creditLines = products.map(p => {
      const productBatches = allBatches.filter(b => String(b.product_id) === String(p.id));
      const price = resolveProductPrice(p, p.brand_id);

      return {
        _product_id: p.id,
        'Item Name': p.product_name,
        'batch_id': null,          // [FIX] Stores the Numeric ID
        'inventory_status': 'Good', // [NEW] Default to Good
        'MRP': Number(p.mrp || 0),
        'Qty': 0,
        'Price': price, 
        'Sch': 0,
        'Disc %': 0,
        'GST %': Number(p.tax_percentage || 0),
        'Invoiced Qty': "Catalog", 
        'Gross $': 0,
        'Disc. $': 0,
        'Taxable $': 0,
        'GST $': 0,
        'Net $': 0,
        'return_to_stock': true,   // [NEW] Default to True
        '_batches': productBatches 
      };
    });
    storeValue('GlobalCreditLinesData', creditLines);
  },

  // --- Initialization Option B: From Invoice (Pre-fill with invoice lines) ---
  loadInvoiceItems: async () => {
    const invoiceId = selInvoice.selectedOptionValue;
    if (!invoiceId) return;

    const allBatches = await getBatch.run();
    await get_invoice_details.run({ id: invoiceId });
    const lines = get_invoice_details.data.lines || [];

    const creditLines = lines.map(line => {
      const productBatches = allBatches.filter(b => String(b.product_id) === String(line.product_id));

      return {
        _product_id: line.product_id,
        'Item Name': line.product_name,
        'batch_id': line.batch_id,  // [FIX] Stores the Numeric ID
        'inventory_status': 'Good',
        'MRP': Number(line.mrp || 0),
        'Qty': 0, 
        'Price': line.rate,
        'Sch': 0,
        'Disc %': 0,
        'GST %': line.tax_percent,
        'Invoiced Qty': line.shipped_qty,
        'Gross $': 0,
        'Disc. $': 0,
        'Taxable $': 0,
        'GST $': 0,
        'Net $': 0,
        'return_to_stock': true,
        '_batches': productBatches 
      };
    });
    storeValue('GlobalCreditLinesData', creditLines);
  },

  // --- Central Update & Calculation Logic ---
  updateRow: () => {
    const change = tblCreditLines.updatedRow; 
    if (!change) return;

    const currentData = appsmith.store.GlobalCreditLinesData || [];
    const targetIndex = currentData.findIndex(row => row._product_id === change._product_id);
    if (targetIndex === -1) return;

    let newData = [...currentData];
    let row = { ...newData[targetIndex], ...change };

    // 1. Batch Auto-fill (Lookup by ID)
    if (change["batch_id"]) {
      const selectedBatch = (row._batches || []).find(b => b.id == change["batch_id"]);
      if (selectedBatch) {
        row['MRP'] = Number(selectedBatch.mrp || 0);

        // Resolve customer specific pricing for the selected batch
        const customerId = selCustomer.selectedOptionValue;
        const customers = getCustomers.data || [];
        const customer = customers.find(c => String(c.id) === String(customerId)) || {};

        let exceptions = [];
        try {
          if (customer.pricing_ex) {
            exceptions = typeof customer.pricing_ex === 'string'
              ? JSON.parse(customer.pricing_ex)
              : customer.pricing_ex;
          }
        } catch (e) {}

        const products = getProducts.data.data || [];
        const product = products.find(p => String(p.id) === String(row._product_id)) || {};

        let rateCol = customer.default_price_col || 'dealer_rate';
        if (Array.isArray(exceptions)) {
          const brandEx = exceptions.find(ex => String(ex.brand_id) === String(product.brand_id));
          if (brandEx && brandEx.price_column) {
            rateCol = brandEx.price_column;
          }
        }

        let price = Number(selectedBatch[rateCol] || 0);
        if (!price) {
          price = Number(selectedBatch.dealer_rate || 0);
        }
        if (!price) {
          price = Number(selectedBatch.mrp || 0);
        }
        row['Price'] = price;
      }
    }

    // 2. Math Processing
    const Qty = Number(row['Qty'] || 0);
    const Price = Number(row['Price'] || 0);    
    const Sch = Number(row['Sch'] || 0);
    const DiscPct = Number(row['Disc %'] || 0);
    const GstPct = Number(row['GST %'] || 0);

    const Gross = Qty * Price;
    const DiscAmt = (Gross - Sch) * (DiscPct / 100);
    const Taxable = Math.max(0, Gross - Sch - DiscAmt);
    const GstAmt = Taxable * (GstPct / 100);
    const Net = Taxable + GstAmt;

    // 3. Save Calculated Values
    newData[targetIndex] = {
      ...row,
      'Gross $': Number(Gross.toFixed(2)),
      'Disc. $': Number(DiscAmt.toFixed(2)),
      'Taxable $': Number(Taxable.toFixed(2)),
      'GST $': Number(GstAmt.toFixed(2)),
      'Net $': Number(Net.toFixed(2))
    };

    storeValue('GlobalCreditLinesData', newData);
  },

  // --- Final Payload Formatting ---
  getFinalItems: () => {
    if (radReturnType.selectedOptionValue === 'FLAT') {
      const total = Number(iptFlatAmount.text || 0);
      const isGst = swiIsGst.isSwitchedOn;
      const taxable = isGst ? total / 1.18 : total;
      const gst = total - taxable;

      return [{
        'Item Name': selAdjType.selectedOptionValue,
        '_product_id': 'FLAT_' + selAdjType.selectedOptionValue,
        'Qty': 1,
        'Price': total,
        'Taxable $': taxable.toFixed(2),
        'GST $': gst.toFixed(2),
        'Net $': total.toFixed(2),
        'GST %': isGst ? 18 : 0,
        'is_gst': isGst,
        'return_to_stock': false,
        'inventory_status': 'Good'
      }];
    } else {
       return (appsmith.store.GlobalCreditLinesData || []).filter(item => Number(item.Qty) > 0);
    }
  }
}

export default {
  // --- EXISTING FUNCTIONS (loadAllProducts, loadInvoiceItems, updateRow, getFinalItems) ---
  // ... (Full code included below for completeness)

  getTaxSummary: () => {
    // 1. Read from the Credit Note store
    const lines = appsmith.store.GlobalCreditLinesData || [];
    const groups = {};

    // Only process items that have a quantity
    const activeLines = lines.filter(row => Number(row.Qty) > 0);

    activeLines.forEach(row => {
      // Group by GST percentage
      const gstPct = row['GST %'] || 0;
      const taxName = gstPct + '% GST';

      if (!groups[taxName]) {
        groups[taxName] = { 
          PARTICULARS: taxName, 
          Pcs: 0, Gross: 0, Sch: 0, Disc: 0, 
          Taxable: 0, Tax: 0, Net: 0 
        };
      }

      const g = groups[taxName];
      g.Pcs     += Number(row['Qty'] || 0);
      g.Gross   += Number(row['Gross $'] || 0);
      g.Sch     += Number(row['Sch'] || 0);
      g.Disc    += Number(row['Disc. $'] || 0); // Note the field name match
      g.Taxable += Number(row['Taxable $'] || 0);
      g.Tax     += Number(row['GST $'] || 0);
      g.Net     += Number(row['Net $'] || 0);
    });

    const resultRows = Object.values(groups);

    // 2. Add Grand Total Row
    if (resultRows.length > 0) {
      const totalRow = resultRows.reduce((acc, curr) => {
        acc.Pcs     += curr.Pcs;
        acc.Gross   += curr.Gross;
        acc.Sch     += curr.Sch;
        acc.Disc    += curr.Disc;
        acc.Taxable += curr.Taxable;
        acc.Tax     += curr.Tax;
        acc.Net     += curr.Net;
        return acc;
      }, { PARTICULARS: 'TOTAL', Pcs: 0, Gross: 0, Sch: 0, Disc: 0, Taxable: 0, Tax: 0, Net: 0 });

      resultRows.push(totalRow);
    }

    // 3. Round all values to 2 decimal places
    return resultRows.map(row => ({
      ...row,
      Gross: Number(row.Gross.toFixed(2)),
      Disc: Number(row.Disc.toFixed(2)),
      Taxable: Number(row.Taxable.toFixed(2)),
      Tax: Number(row.Tax.toFixed(2)),
      Net: Number(row.Net.toFixed(2))
    }));
  },

  // --- REST OF THE FUNCTIONS ---
  loadAllProducts: async () => { /* ... see previous code ... */ },
  loadInvoiceItems: async () => { /* ... see previous code ... */ },
  updateRow: () => { /* ... see previous code ... */ },
  getFinalItems: () => { /* ... see previous code ... */ }
}

