export default {
  // Client-side PDF compile
  generatePDF: async () => {
    try {
      if (typeof jspdf === "undefined") {
        throw new Error("jsPDF library not loaded. Please install it in Appsmith Settings -> Libraries.");
      }
      const jsPDFConstructor = jspdf.jsPDF || jspdf;
      const doc = new jsPDFConstructor('p', 'pt', 'a4');
      const pageWidth = doc.internal.pageSize.width;
      const pageHeight = doc.internal.pageSize.height;
      const margin = 45; // slightly wider margins for professional print

      // Header Logo and Details from Global_Assets
      try {
        const logo = Global_Assets.getLogo();
        if (logo && logo.startsWith("data:image/")) {
          // FAST compression preserves original resolution.
          // Coordinates adjusted for a balanced top header layout
          doc.addImage(logo, 'PNG', margin, 35, 120, 36, undefined, 'FAST');
        } else {
          doc.setFont("helvetica", "bold");
          doc.setFontSize(20);
          doc.setTextColor(33, 136, 255);
          doc.text(Global_Assets.getSummary().regt_name, margin, 60);
        }
      } catch (e) {
        console.warn("Logo rendering failed:", e);
      }

      // Company Info Text aligned to top right
      const summary = Global_Assets.getSummary();
      doc.setFont("helvetica", "bold");
      doc.setFontSize(9);
      doc.setTextColor(15, 23, 42); // Primary Dark Text
      doc.text(summary.regt_name, pageWidth - margin, 42, { align: "right" });

      doc.setFont("helvetica", "normal");
      doc.setFontSize(8.5);
      doc.setTextColor(100, 116, 139); // Slate secondary text
      doc.text(summary.address, pageWidth - margin, 54, { align: "right" });
      doc.text(`${summary.District}, ${summary.state} - ${summary.pin}`, pageWidth - margin, 65, { align: "right" });
      doc.text(`Tel: ${summary.contact_no} | Email: ${summary.email} | GSTIN: ${summary.gst}`, pageWidth - margin, 76, { align: "right" });

      // Clean Blue Accent Line
      doc.setDrawColor(33, 136, 255);
      doc.setLineWidth(1.5);
      doc.line(margin, 88, pageWidth - margin, 88);

      // Ref & Date with clean separation
      doc.setFontSize(9.5);
      doc.setTextColor(71, 85, 105);
      doc.setFont("helvetica", "bold");
      doc.text("Ref: " + (tblHistory.selectedRow ? tblHistory.selectedRow.letter_code : "GN-LET-DRAFT"), margin, 115);

      const dateStr = new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' });
      doc.setFont("helvetica", "normal");
      doc.text("Date: " + dateStr, pageWidth - margin, 115, { align: "right" });

      // Recipient Address (To Box)
      doc.setFont("helvetica", "bold");
      doc.setTextColor(15, 23, 42);
      doc.text("To,", margin, 145);
      doc.text(inpRecipientName.text || "Recipient Name", margin, 160);

      doc.setFont("helvetica", "normal");
      const addrLines = doc.splitTextToSize(inpRecipientAddress.text || "", 260);
      doc.text(addrLines, margin, 172);

      // Subject line with spacing and bold typeface
      const subjectY = 185 + (addrLines.length * 12);
      doc.setFont("helvetica", "bold");
      doc.text("Subject: " + (inpSubject.text || ""), margin, subjectY);

      // Rich Text Body rendering and HTML entity resolving
      const bodyHtml = rteLetterBody.text || "";
      let cleanBody = bodyHtml
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/p>/gi, '\n\n')
        .replace(/<h[1-6]>/gi, '\n')
        .replace(/<\/h[1-6]>/gi, '\n')
        .replace(/<li>/gi, '  • ')
        .replace(/<\/li>/gi, '\n')
        .replace(/<[^>]+>/g, '') // Strip remaining HTML tags
        .replace(/&nbsp;/gi, ' ') // Resolve non-breaking spaces
        .replace(/&amp;/gi, '&')
        .replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>')
        .replace(/&quot;/gi, '"')
        .replace(/&#39;/gi, "'");

      const bodyY = subjectY + 25;
      doc.setFont("helvetica", "normal");
      doc.setTextColor(30, 41, 59); // Slate-800 for warm body color
      const bodyLines = doc.splitTextToSize(cleanBody, pageWidth - (margin * 2));
      doc.text(bodyLines, margin, bodyY);

      // Sign-off signature section
      const sigY = bodyY + (bodyLines.length * 13) + 45;
      doc.setFont("helvetica", "normal");
      doc.setTextColor(15, 23, 42);
      doc.text("Yours Sincerely,", margin, sigY);
      doc.setFont("helvetica", "bold");
      doc.text(inpSignatory.text || "Signatory", margin, sigY + 38);
      doc.setFont("helvetica", "normal");
      doc.text(inpDesignation.text || "Designation", margin, sigY + 50);
      doc.text(summary.regt_name, margin, sigY + 62);

      // Footer divider & text
      doc.setDrawColor(226, 232, 240);
      doc.setLineWidth(1.0);
      doc.line(margin, pageHeight - 60, pageWidth - margin, pageHeight - 60);

      doc.setFontSize(7.5);
      doc.setTextColor(148, 163, 184); // light gray text for footer
      doc.text("Bank Details: Axis Bank Ltd | A/c No: 912345678901234 | IFSC: UTIB0000001", margin, pageHeight - 46);
      doc.text(`CIN: U74140KA2026PTC123456 | Confidentiality Notice: This document contains official corporate communication.`, margin, pageHeight - 34);

      const fileName = `Official_Letter_${(inpRecipientName.text || "Recipient").replace(/\s+/g, '_')}.pdf`;
      download(doc.output('dataurlstring'), fileName, "application/pdf");
      showAlert("PDF compiled and downloaded successfully!", "success");
    } catch (err) {
      showAlert("PDF compile error: " + err.message, "error");
    }
  },

  // Send Email Action
  sendEmail: async () => {
    if (!inpRecipientName.text || !inpSubject.text || !rteLetterBody.text || !inpSignatory.text) {
      showAlert("Please enter all required fields: Recipient Name, Subject, Letter Body, and Signatory Name.", "warning");
      return;
    }
    await apiSendLetter.run(
      () => {
        showAlert("Letter successfully sent and logged!", "success");
        apiGetLetters.run();
      },
      (err) => {
        showAlert("Email dispatch failed: " + err.message, "error");
      }
    );
  }
}

