export default {

	// ============================================================
	// TEMPLATE COLUMNS — the flat file now carries EVERYTHING
	// (customer details + MRP/HSN included), so no separate lookup
	// is needed. One row per invoice line/batch; customer + header
	// fields just repeat on every row for that invoice_number.
	// ============================================================
	templateColumns: [
		"invoice_id", "invoice_number", "invoice_date",
		"customer_id", "customer_name", "customer_address", "district",
		"pin_code", "gstin", "customer_phone", "customer_email",
		"dse_name", "dse_phone", "route",
		"product_id", "product_name", "product_code", "ean_code", "hsn_code",
		"brand_id", "brand_name",
		"shipped_qty", "selling_rate", "mrp",
		"tax_percent", "tax_amount", "gross_amount", "scheme_amount",
		"discount_percent", "discount_amount", "taxable_sales_value", "net_sales_value",
		"batch_id", "batch_code", "expiry_date", "tier_applied"
	],

	// ============================================================
	// Downloads a blank CSV template (headers + one example row)
	// for you to fill in and re-upload via the FilePicker.
	// Wire to a button: {{ InvoiceUtils.downloadTemplate() }}
	// ============================================================
	downloadTemplate() {
		const exampleRow = {
			invoice_id: "3022",
			invoice_number: "INV-26-2167",
			invoice_date: "2026-06-30",
			customer_id: "217",
			customer_name: "P B S Associates",
			customer_address: "61/9648 Big Bazar, Kozhikode, Big Bazar",
			district: "Kozhikode",
			pin_code: "673001",
			gstin: "32ABCFP3910B1ZZ",
			customer_phone: "-",
			customer_email: "-",
			dse_name: "Syed Anfal",
			dse_phone: "9567987408",
			route: "Friday",
			product_id: "168",
			product_name: "RG GINGELLY OIL 200 ML",
			product_code: "RG-EDI-003",
			ean_code: "",
			hsn_code: "15155091",
			brand_id: "8",
			brand_name: "Rg Foods",
			shipped_qty: "93",
			selling_rate: "48.08",
			mrp: "50.00",
			tax_percent: "5",
			tax_amount: "223.57",
			gross_amount: "4471.44",
			scheme_amount: "0",
			discount_percent: "0",
			discount_amount: "0",
			taxable_sales_value: "4471.44",
			net_sales_value: "4695.01",
			batch_id: "1644",
			batch_code: "02745FCAWS548",
			expiry_date: "2027-03-01",
			tier_applied: ""
		};

		const escapeCsv = (val) => {
			const s = String(val ?? "");
			return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
		};

		const header = this.templateColumns.join(",");
		const row = this.templateColumns.map((c) => escapeCsv(exampleRow[c])).join(",");
		const csv = header + "\n" + row + "\n";

		download(csv, "invoice_upload_template.csv", "text/csv");
		showAlert("Template downloaded", "success");
	},

	// ============================================================
	// ENTRY POINT — call this from a button:
	//   InvoiceUtils.generateInvoicesFromFile(FilePicker1.files[0].data)
	//
	// FilePicker widget setup:
	//   - Accept: .csv, .xlsx
	//   - "Data Format" / parsing option set so files[0].data
	//     resolves to an ARRAY OF OBJECTS (Appsmith auto-parses
	//     CSV/XLSX when this is enabled). Column headers should
	//     match templateColumns above (case-insensitive is fine).
	// ============================================================
	async generateInvoicesFromFile(fileData) {
		try {
			if (!fileData || fileData.length === 0) {
				throw new Error("No data found. Please upload a file first.");
			}

			const grouped = this.groupRows(fileData);
			const invoiceNumbers = Object.keys(grouped);

			if (invoiceNumbers.length === 0) {
				throw new Error("No valid invoice_number found in the uploaded file.");
			}

			// Generate one PDF per invoice_number found in the file.
			// Downloads are staggered slightly so the browser doesn't
			// block multiple simultaneous file downloads.
			for (let i = 0; i < invoiceNumbers.length; i++) {
				const invNo = invoiceNumbers[i];
				await this.previewInvoice(grouped[invNo]);
				if (i < invoiceNumbers.length - 1) {
					await new Promise((resolve) => setTimeout(resolve, 700));
				}
			}

			showAlert(`Generated ${invoiceNumbers.length} invoice(s) successfully`, "success");
		} catch (error) {
			showAlert("Bulk Invoice Error: " + error.message, "error");
		}
	},

	// ============================================================
	// Groups flat rows (one row per invoice line / batch) into the
	// invoiceData shape previewInvoice() expects, keyed by
	// invoice_number.
	// ============================================================
	groupRows(rows) {
		const groups = {};

		rows.forEach((raw) => {
			const row = this.normalizeRow(raw);
			const key = row.invoice_number;
			if (!key) return; // skip malformed rows

			if (!groups[key]) {
				const fallback = this.getCustomerDetails(row.customer_id);
				groups[key] = {
					invoice_id: row.invoice_id || key,
					invoice_number: row.invoice_number,
					invoice_date: row.invoice_date,
					order_date: row.invoice_date,
					customer_id: row.customer_id,
					customer_name: row.customer_name,
					// Pulled straight from the uploaded row now. Falls back
					// to a Customers lookup only if the file leaves them
					// blank — see getCustomerDetails() below.
					customer_address: row.customer_address || fallback.customer_address,
					district: row.district || fallback.district,
					pin_code: row.pin_code || fallback.pin_code,
					gstin: row.gstin || fallback.gstin,
					customer_phone: row.customer_phone || fallback.customer_phone,
					customer_email: row.customer_email || fallback.customer_email,
					dse_name: row.dse_name || fallback.dse_name,
					dse_phone: row.dse_phone || fallback.dse_phone,
					route: row.route || fallback.route,
					grand_total: 0,
					invoice_lines: []
				};
			}

			const g = groups[key];

			// If lines in the same invoice carry different dates,
			// keep the latest one as the header invoice/order date.
			if (row.invoice_date && new Date(row.invoice_date) > new Date(g.invoice_date)) {
				g.invoice_date = row.invoice_date;
				g.order_date = row.invoice_date;
			}

			g.invoice_lines.push({
				product_name: row.product_name,
				ean_code: row.ean_code || "-",
				hsn_code: row.hsn_code || "-",
				batch_code: row.batch_code || "-",
				expiry_date: row.expiry_date || null,
				mrp: row.mrp || row.selling_rate || 0,
				shipped_qty: row.shipped_qty,
				rate: row.selling_rate,
				gross_amount: row.gross_amount,
				scheme_amount: row.scheme_amount,
				discount_percent: row.discount_percent,
				discount_amount: row.discount_amount,
				taxable_amount: row.taxable_sales_value,
				tax_percent: row.tax_percent,
				tax_amount: row.tax_amount,
				amount: row.net_sales_value,
				tier_applied: row.tier_applied || (row.scheme_amount > 0 ? "Scheme Applied" : null)
			});

			g.grand_total += Number(row.net_sales_value || 0);
		});

		Object.values(groups).forEach((g) => {
			g.grand_total = Math.round(g.grand_total * 100) / 100;
		});

		return groups;
	},

	// ============================================================
	// Normalizes column name/casing differences coming from the
	// uploaded file so groupRows() always sees consistent keys.
	// ============================================================
	normalizeRow(raw) {
		const get = (...keys) => {
			for (const k of keys) {
				if (raw[k] !== undefined && raw[k] !== null && raw[k] !== "") return raw[k];
				const found = Object.keys(raw).find((rk) => rk.toLowerCase() === k.toLowerCase());
				if (found && raw[found] !== "") return raw[found];
			}
			return undefined;
		};

		return {
			invoice_id: get("invoice_id"),
			invoice_number: get("invoice_number"),
			invoice_date: get("invoice_date"),
			customer_id: get("customer_id"),
			customer_name: get("customer_name"),
			customer_address: get("customer_address", "address"),
			district: get("district"),
			pin_code: get("pin_code", "pincode", "pin"),
			gstin: get("gstin", "gst_number"),
			customer_phone: get("customer_phone", "phone"),
			customer_email: get("customer_email", "email"),
			dse_name: get("dse_name", "dse"),
			dse_phone: get("dse_phone"),
			route: get("route"),
			product_id: get("product_id"),
			product_name: get("product_name"),
			product_code: get("product_code"),
			ean_code: get("ean_code"),
			hsn_code: get("hsn_code"),
			brand_id: get("brand_id"),
			brand_name: get("brand_name"),
			shipped_qty: Number(get("shipped_qty") || 0),
			selling_rate: Number(get("selling_rate") || 0),
			mrp: Number(get("mrp") || 0),
			tax_percent: Number(get("tax_percent") || 0),
			tax_amount: Number(get("tax_amount") || 0),
			gross_amount: Number(get("gross_amount") || 0),
			scheme_amount: Number(get("scheme_amount") || 0),
			discount_percent: Number(get("discount_percent") || 0),
			discount_amount: Number(get("discount_amount") || 0),
			taxable_sales_value: Number(get("taxable_sales_value") || 0),
			net_sales_value: Number(get("net_sales_value") || 0),
			batch_id: get("batch_id"),
			batch_code: get("batch_code"),
			expiry_date: get("expiry_date"),
			tier_applied: get("tier_applied")
		};
	},

	// ============================================================
	// FALLBACK ONLY — used when a row's customer/DSE columns are
	// left blank in the uploaded file. Since the template now
	// includes these columns directly, this rarely fires. Wire it
	// to a real Customers datasource if you want auto-fill instead
	// of requiring them in every upload, e.g.:
	//
	//   getCustomerDetails(customerId) {
	//     const c = Customers.data.find(c => String(c.customer_id) === String(customerId));
	//     if (!c) return this._blankCustomer();
	//     return {
	//       customer_address: c.address,
	//       district: c.district,
	//       pin_code: c.pin_code,
	//       gstin: c.gstin,
	//       customer_phone: c.phone,
	//       customer_email: c.email,
	//       dse_name: c.dse_name,
	//       dse_phone: c.dse_phone,
	//       route: c.route
	//     };
	//   },
	// ============================================================
	getCustomerDetails(customerId) {
		return this._blankCustomer();
	},

	_blankCustomer() {
		return {
			customer_address: "-",
			district: "-",
			pin_code: "-",
			gstin: "-",
			customer_phone: "-",
			customer_email: "-",
			dse_name: "-",
			dse_phone: "-",
			route: "-"
		};
	},

	// ============================================================
	// ORIGINAL PDF GENERATOR — UNCHANGED.
	// This is exactly what produced your sample invoice, so the
	// output stays pixel-identical. Do not modify unless you also
	// want to change the layout.
	// ============================================================
	async previewInvoice(invoiceData) {
		try {
			if (!invoiceData || !invoiceData.invoice_id) throw new Error("No Invoice data selected.");

			// --- 1. LIBRARY SAFETY ---
			if (typeof jspdf === "undefined") throw new Error("jspdf library not loaded.");
			const jsPDFConstructor = jspdf.jsPDF || jspdf;
			const doc = new jsPDFConstructor('p', 'pt', 'a4');

			if (typeof doc.autoTable !== "function" && jspdf.plugin && jspdf.plugin.autotable) {
				jsPDFConstructor.API.autoTable = jspdf.plugin.autotable;
			}

			const lines = invoiceData.invoice_lines || [];
			const summaryData = this.getSummary(lines);
			const grandTotal = Number(invoiceData.grand_total || 0);
			const brand = Global_Assets.getSummary();

			await getBankDetails.run();
			const bank = getBankDetails.data || {};

			const margin = 12;
			const pageWidth = doc.internal.pageSize.width;

			const toWords = (num) => {
				const a = ['','One ','Two ','Three ','Four ', 'Five ','Six ','Seven ','Eight ','Nine ','Ten ','Eleven ','Twelve ','Thirteen ','Fourteen ','Fifteen ','Sixteen ','Seventeen ','Eighteen ','Nineteen '];
				const b = ['', '', 'Twenty','Thirty','Forty','Fifty', 'Sixty','Seventy','Eighty','Ninety'];
				const n = ("000000000" + Math.floor(num)).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/);
				if (!n) return '';
				let str = '';
				str += (Number(n[1]) != 0) ? (a[Number(n[1])] || b[n[1][0]] + ' ' + a[n[1][1]]) + 'Crore ' : '';
				str += (Number(n[2]) != 0) ? (a[Number(n[2])] || b[n[2][0]] + ' ' + a[n[2][1]]) + 'Lakh ' : '';
				str += (Number(n[3]) != 0) ? (a[Number(n[3])] || b[n[3][0]] + ' ' + a[n[3][1]]) + 'Thousand ' : '';
				str += (Number(n[4]) != 0) ? (a[Number(n[4])] || b[n[4][0]] + ' ' + a[n[4][1]]) + 'Hundred ' : '';
				str += (Number(n[5]) != 0) ? ((str != '') ? 'and ' : '') + (a[Number(n[5])] || b[n[5][0]] + ' ' + a[n[5][1]]) + 'Only ' : 'Only ';
				return str;
			};

			const drawMainHeader = (currentPage, totalPages) => {
				const headerY = margin;
				try {
					const logo = Global_Assets.getLogo();
					if (logo.startsWith("data:image/")) {
						doc.addImage(logo, 'PNG', margin, headerY, 90, 30);
					}
				} catch(e) {}

				doc.setTextColor(0, 0, 0);
				doc.setFont("helvetica", "bold");
				doc.setFontSize(16);
				doc.text("SALES INVOICE", pageWidth / 2, headerY + 15, { align: "center" });
				doc.setFontSize(11);
				doc.text(String(invoiceData.invoice_number), pageWidth / 2, headerY + 30, { align: "center" });

				const boxesY = headerY + 40;
				const gap = 8;
				const boxWidth = (pageWidth - (margin * 2) - (gap * 2)) / 3;
				const boxHeight = 95;

				this._drawSimpleBox(doc, margin, boxesY, boxWidth, boxHeight, [
					["From", String(brand.regt_name)],
					["Address", String(brand.address)],
					["Dist/PIN", `${brand.District} - ${brand.pin}`],
					["GST", String(brand.gst)],
					["FSSAI", String(brand.fssai_no)],
					["Email", String(brand.email)],
					["Contact No", String(brand.contact_no)]
				]);

				const cAddr = [invoiceData.customer_address, invoiceData.district, invoiceData.pin_code ? "PIN: " + invoiceData.pin_code : null].filter(Boolean).join(", ");
				this._drawSimpleBox(doc, margin + boxWidth + gap, boxesY, boxWidth, boxHeight, [
					["To", String(invoiceData.customer_name)],
					["Address", cAddr || "-"],
					["GSTIN", String(invoiceData.gstin || "-")],
					["Phone", String(invoiceData.customer_phone || "-")],
					["Email", String(invoiceData.customer_email || "-")]
				], 60);

				this._drawSimpleBox(doc, margin + (boxWidth * 2) + (gap * 2), boxesY, boxWidth, boxHeight, [
					["INV No", String(invoiceData.invoice_number)],
					["Date", moment(invoiceData.invoice_date).format("DD/MM/YYYY")],
					["Order Date", moment(invoiceData.order_date).format("DD/MM/YYYY")],
					["TOTAL AMT", Number(grandTotal).toFixed(2)],
					["DSE", String(invoiceData.dse_name || "-")],
					["Route", String(invoiceData.route || "-")],
					["DSE Phone", String(invoiceData.dse_phone || "-")],
					["PAGE", `${currentPage} / ${totalPages}`]
				], 65);

				return boxesY + boxHeight;
			};

			// --- 2. ITEMS TABLE ---
			doc.autoTable({
				startY: margin + 40 + 95 + 10,
				margin: { left: margin, right: margin, top: 157, bottom: 12 },
				head: [["S.N", "ITEM NAME", "EAN CODE", "HSN", "BATCH\nEXPIRY", "MRP", "QTY", "PRICE", "GROSS", "SCH", "D%", "D.AMT", "TXBL", "GST%", "GST$", "NET$"]],
				body: lines.map((row, index) => {
					const expiryStr = row.expiry_date ? moment(row.expiry_date).format("MM/YY") : "-";
					return [
						index + 1,
						row.product_name,
						row.ean_code || "-",
						row.hsn_code || "-",
						`${row.batch_code || ""}\n${expiryStr}`,
						Number(row.mrp || 0).toFixed(2),
						row.shipped_qty,
						Number(row.rate || 0).toFixed(2),
						Number(row.gross_amount || 0).toFixed(2),
						Number(row.scheme_amount || 0).toFixed(2),
						(row.discount_percent || 0) + "%",
						Number(row.discount_amount || 0).toFixed(2),
						Number(row.taxable_amount || 0).toFixed(2),
						(row.tax_percent || 0) + "%",
						Number(row.tax_amount || 0).toFixed(2),
						Number(row.amount || 0).toFixed(2)
					];
				}),
				didDrawPage: (data) => {
					drawMainHeader(data.pageNumber, doc.internal.getNumberOfPages());
				},
				theme: 'grid',
				styles: { fontSize: 8, cellPadding: 2, lineColor: [0, 0, 0], lineWidth: 0.5, textColor: [0, 0, 0], overflow: 'linebreak', valign: 'middle' },
				headStyles: { fillColor: [255, 255, 255], textColor: [0, 0, 0], fontStyle: 'bold', lineWidth: 0.5 },
				columnStyles: {
					0: { cellWidth: 20 }, 1: { cellWidth: 'auto', minCellWidth: 100 }, 2: { cellWidth: 45 }, 3: { cellWidth: 35 }, 4: { cellWidth: 45 },
					5: { halign: 'right' }, 6: { halign: 'right' }, 7: { halign: 'right' }, 8: { halign: 'right' }, 9: { halign: 'right' }, 10: { halign: 'right' },
					11: { halign: 'right' }, 12: { halign: 'right' }, 13: { halign: 'center' }, 14: { halign: 'right' }, 15: { halign: 'right' }
				}
			});

			let currentY = doc.lastAutoTable.finalY + 20;
			const pageHeight = doc.internal.pageSize.height;

			let totalSchemeAmt = 0;
			let schemeLines = (invoiceData.invoice_lines || [])
			.filter(l => l.tier_applied)
			.map(l => {
				const amt = Number(l.scheme_amount || 0);
				totalSchemeAmt += amt;
				return [l.product_name, l.tier_applied, amt.toFixed(2)];
			});

			if (schemeLines.length === 0) {
				schemeLines = (invoiceData.order_lines || [])
					.filter(l => l.tier_applied)
					.map(l => {
					const amt = Number(l.scheme_amount || 0);
					totalSchemeAmt += amt;
					return [l.product_name, l.tier_applied, amt.toFixed(2)];
				});
			}

			if (schemeLines.length > 0) {
				schemeLines.push([{ content: 'Total Scheme Discount', colSpan: 2, styles: { halign: 'right', fontStyle: 'bold' } }, { content: totalSchemeAmt.toFixed(2), styles: { halign: 'right', fontStyle: 'bold' } }]);
			}

			const estimatedFooterHeight = (summaryData.length * 20) + (schemeLines.length * 20) + 210;
			if (currentY + estimatedFooterHeight > pageHeight) {
				doc.addPage();
				drawMainHeader(doc.internal.getNumberOfPages(), doc.internal.getNumberOfPages());
				currentY = 157;
			}

			// --- 3. TAX SUMMARY ---
			doc.autoTable({
				startY: currentY,
				margin: { left: margin },
				head: [["TAX SUMMARY", "PCS", "GROSS", "SCH", "DISC", "TAXABLE", "TAX", "NET"]],
				body: summaryData.map(row => [
					row.PARTICULARS, row.Pcs, row.Gross, row.Sch,
					row.Disc, row.Taxable, row.Tax, row.Net
				]),
				theme: 'grid',
				styles: { fontSize: 8.5, cellPadding: 2, lineColor: [0, 0, 0], lineWidth: 0.5, textColor: [0, 0, 0] },
				headStyles: { fillColor: [255, 255, 255], textColor: [0, 0, 0], fontStyle: 'bold' },
				bodyStyles: (row) => (row.at(0).includes('Total') ? { fontStyle: 'bold', fillColor: [250, 250, 250] } : {})
			});

			// --- 4. SCHEMES APPLIED ---
			if (schemeLines.length > 0) {
				doc.autoTable({
					startY: doc.lastAutoTable.finalY + 10,
					margin: { left: margin },
					head: [["PRODUCT NAME", "SCHEMES / TIER APPLIED", "SCHEME AMT"]],
					body: schemeLines,
					theme: 'grid',
					styles: { fontSize: 8, cellPadding: 3, lineColor: [0, 0, 0], lineWidth: 0.5, textColor: [0, 0, 0] },
					headStyles: { fillColor: [245, 245, 245], textColor: [0, 0, 0], fontStyle: 'bold' },
					columnStyles: { 0: { cellWidth: 150 }, 1: { cellWidth: 'auto' }, 2: { cellWidth: 70, halign: 'right' } }
				});
			}

			// --- 5. AMOUNT IN WORDS & ACKNOWLEDGEMENT ---
			const wordsY = doc.lastAutoTable.finalY + 38;
			doc.setFontSize(10.5); doc.setFont("helvetica", "bold");
			doc.text(`Grand Total: ${Number(grandTotal).toFixed(2)}`, margin, wordsY - 14);
			doc.text("Total Amount (in words):", margin, wordsY);
			doc.setFont("helvetica", "normal");
			doc.text(toWords(Math.round(grandTotal)), margin + 140, wordsY);

			doc.setFontSize(8.5);
			doc.text("This is a computer generated document and does not require a physical signature.", margin, pageHeight - 170);

			const slipY = pageHeight - 160;
			doc.setDrawColor(0, 0, 0); doc.setLineDash([3, 3], 0);
			doc.line(margin, slipY, pageWidth - margin, slipY); doc.setLineDash([], 0);

			doc.setFontSize(10); doc.setFont("helvetica", "bold");
			doc.text("RECEIPT ACKNOWLEDGEMENT", pageWidth / 2, slipY + 20, { align: "center" });

			const slipBoxY = slipY + 30;
			doc.rect(margin, slipBoxY, pageWidth - (margin * 2), 100);

			doc.setFontSize(9);
			doc.text(`Invoice No: ${invoiceData.invoice_number}`, margin + 10, slipBoxY + 15);
			doc.text(`Date: ${moment(invoiceData.invoice_date).format("DD/MM/YYYY")}`, margin + 10, slipBoxY + 30);
			doc.text(`Customer: ${invoiceData.customer_name}`, margin + 10, slipBoxY + 45);
			doc.text(`Total Amount: ${Number(grandTotal).toFixed(2)}`, margin + 10, slipBoxY + 60);

			const bankInfoX = pageWidth / 2 + 5;
			doc.setFont("helvetica", "bold"); doc.text("PAYMENT BANK DETAILS", bankInfoX, slipBoxY + 15);
			doc.setFont("helvetica", "normal"); doc.setFontSize(8);
			doc.text(`Bank: ${bank.bank_name || "-"}`, bankInfoX, slipBoxY + 28);
			doc.text(`Acc No: ${bank.account_number || "-"}`, bankInfoX, slipBoxY + 38);
			doc.text(`IFSC: ${bank.ifsc_code || "-"}`, bankInfoX, slipBoxY + 48);

			doc.setFontSize(9);
			doc.text(`Receiver's Signature: __________________`, margin + 10, slipBoxY + 90);
			doc.text(`Authorized Signatory: __________________`, bankInfoX, slipBoxY + 90);

			doc.setFontSize(8); doc.setFont("helvetica", "bold");
			doc.text("Terms and Condition: ALL LEGAL DISPUTES ARE SUBJECT TO CALICUT JURIDICTION ONLY", margin, pageHeight - 15);

			const fileName = (invoiceData.invoice_number || "INV") + ".pdf";
			download(doc.output('dataurlstring'), fileName, "application/pdf");
			showAlert("Invoice Downloaded Successfully", "success");

		} catch (error) {
			showAlert("Invoice PDF Error: " + error.message, "error");
		}
	},

	getSummary(lines) {
		if (!lines || lines.length === 0) return [];
		const groups = {};
		lines.forEach(row => {
			const taxRate = Number(row.tax_percent || 0);
			const taxName = taxRate > 0 ? `${taxRate}% GST` : 'No Tax';
			if (!groups[taxName]) {
				groups[taxName] = { PARTICULARS: taxName, Pcs: 0, Gross: 0, Sch: 0, Disc: 0, Taxable: 0, Tax: 0, Net: 0 };
			}
			const g = groups[taxName];
			g.Pcs += Number(row.shipped_qty || 0); g.Gross += Number(row.gross_amount || 0); g.Sch += Number(row.scheme_amount || 0);
			g.Disc += Number(row.discount_amount || 0); g.Taxable += Number(row.taxable_amount || 0); g.Tax += Number(row.tax_amount || 0); g.Net += Number(row.amount || 0);
		});
		const resultRows = Object.values(groups);
		if (resultRows.length > 0) {
			const totalRow = resultRows.reduce((acc, curr) => {
				acc.Pcs += curr.Pcs; acc.Gross += curr.Gross; acc.Sch += curr.Sch; acc.Disc += curr.Disc; acc.Taxable += curr.Taxable; acc.Tax += curr.Tax; acc.Net += curr.Net;
				return acc;
			}, { PARTICULARS: 'Grand Total', Pcs: 0, Gross: 0, Sch: 0, Disc: 0, Taxable: 0, Tax: 0, Net: 0 });
			resultRows.push(totalRow);
		}
		return resultRows.map(row => ({
			PARTICULARS: row.PARTICULARS, Pcs: row.Pcs, Gross: row.Gross.toFixed(2), Sch: row.Sch.toFixed(2),
			Disc: row.Disc.toFixed(2), Taxable: row.Taxable.toFixed(2), Tax: row.Tax.toFixed(2), Net: Math.round(row.Net).toFixed(2)
		}));
	},

	_drawSimpleBox(doc, x, y, width, height, rows, labelWidth = 58) {
		doc.setDrawColor(0, 0, 0); doc.setLineWidth(0.5); doc.rect(x, y, width, height);
		let rowY = y + 11;
		rows.forEach(r => {
			doc.setFontSize(8.5); doc.setFont("helvetica", "bold"); doc.setTextColor(0, 0, 0);
			const label = String(r[0]) + ":"; doc.text(label, x + 5, rowY);
			doc.setFont("helvetica", "normal");
			const val = String(r[1] || "-");
			const splitVal = doc.splitTextToSize(val, width - labelWidth - 5);
			doc.text(splitVal, x + labelWidth, rowY); rowY += (splitVal.length * 9.5) + 1.5;
		});
	}
}

